+        trigger.addEventListener('click', event => {
+          event.preventDefault();
+          const fromPointer = pointerTrigger === trigger;
+          pointerTrigger = null;
+          if (isOpen(menu)) {
+            closeAndRestore(menu, { fromPointer });
+          } else {
+            if (!fromPointer) {
+              enterOnOpen.add(menu);
+            }
+            showMenu(menu, trigger);
+          }
+        });
+      } else {
+        trigger.addEventListener('click', () => {
+          const fromPointer = pointerTrigger === trigger;
+          pointerTrigger = null;
+          if (!fromPointer && !isOpen(menu)) {
+            enterOnOpen.add(menu);
+          }
+        });
+      }
+
+      // Preview on focus (both top-level menubar triggers and submenu triggers)
+      trigger.addEventListener('focus', () => {
+        if (windowBlurred || returningFromOwnMenu) {
+          returningFromOwnMenu = false;
+          return;
+        }
+        showMenu(menu, trigger);
+      });
+
+      trigger.addEventListener('blur', event => {
+        const nextFocus = event.relatedTarget;
+        if (nextFocus && menu.contains(nextFocus)) return;
+        if (isOpen(menu)) {
+          menu.hidePopover();
+        }
+      });
+
+      if (isRoot) {
+        // Hover switches open menus in the menubar
+        trigger.addEventListener('pointerenter', () => {
+          const anyRootOpen = rootTriggers.some(t => t !== trigger && isOpen(menuFor(t)));
+          if (!anyRootOpen) return;
+          rootTriggers.forEach(t => {
+            if (t !== trigger && isOpen(menuFor(t))) {
+              menuFor(t).hidePopover();
+            }
+          });
+          rootTriggers.forEach(t => { t.tabIndex = t === trigger ? 0 : -1; });
+          trigger.focus({ preventScroll: true, focusVisible: false });
+          showMenu(menu, trigger);
+        });
+
+        trigger.addEventListener('keydown', event => {
+          const group = menu.querySelector('[focusgroup~="menu"]');
+          const items = group ? getMenuItems(group) : [];
+
+          if (event.key === 'ArrowRight') {
+            event.preventDefault();
+            moveToRootTrigger(trigger, 1);
+          } else if (event.key === 'ArrowLeft') {
+            event.preventDefault();
+            moveToRootTrigger(trigger, -1);
+          } else if (event.key === 'ArrowDown') {
+            event.preventDefault();
+            if (isOpen(menu)) {
+              items[0]?.focus({ preventScroll: true });
+            } else {
+              enterOnOpen.add(menu);
+              trigger.click();
+            }
+          } else if (event.key === 'Home' || event.key === 'End') {
+            event.preventDefault();
+            showMenu(menu, trigger);
+            const target = event.key === 'Home' ? items[0] : items[items.length - 1];
+            target?.focus({ preventScroll: true });
+          } else if (event.key === 'Escape' && isOpen(menu)) {
+            event.preventDefault();
+            returningFromOwnMenu = true;
+            menu.hidePopover();
+          }
+        });
+      } else {
+        // Submenu trigger
+        trigger.addEventListener('pointerleave', event => {
+          startBridge(menu, event);
+        });
+
+        trigger.addEventListener('keydown', event => {
+          const group = menu.querySelector('[focusgroup~="menu"]');
+          const items = group ? getMenuItems(group) : [];
+
+          if (event.key === 'ArrowRight') {
+            event.preventDefault();
+            event.stopPropagation();
+            showMenu(menu, trigger);
+            items[0]?.focus({ preventScroll: true });
+          }
+        });
