+  <script>
+    document.querySelectorAll('.customizations-group').forEach((group) => {
+      const selectAll = group.querySelector('.js-select-all');
+      const items = Array.from(group.querySelectorAll('.js-item-checkbox:not(:disabled)'));
+      if (!selectAll || items.length === 0) return;
+
+      const syncSelectAll = () => {
+        const checkedCount = items.filter((item) => item.checked).length;
+        selectAll.checked = checkedCount === items.length;
+        selectAll.indeterminate = checkedCount > 0 && checkedCount < items.length;
+      };
+
+      selectAll.addEventListener('change', () => {
+        selectAll.indeterminate = false;
+        items.forEach((item) => {
+          item.checked = selectAll.checked;
+        });
+      });
+
+      items.forEach((item) => {
+        item.addEventListener('change', syncSelectAll);
+      });
+
+      syncSelectAll();
+    });
+  </script>
