+  const SUITES = {
+    'HYBRID-X25519-MLKEM768': {
+      id: 'HYBRID-X25519-MLKEM768',
+      label: 'Hybrid Post-Quantum (X25519 + ML-KEM-768)',
+      kemType: 'hybrid',
+      curve: 'X25519',
+      pq: 'ML-KEM-768',
+      aead: 'AES-256-GCM',
+      kdf: 'HKDF-SHA256'
+    },
+    'HYBRID-P256-MLKEM768': {
+      id: 'HYBRID-P256-MLKEM768',
+      label: 'Hybrid Post-Quantum (ECDH P-256 + ML-KEM-768)',
+      kemType: 'hybrid',
+      curve: 'P-256',
+      pq: 'ML-KEM-768',
+      aead: 'AES-256-GCM',
+      kdf: 'HKDF-SHA256'
+    },
+    'PQ-MLKEM768': {
+      id: 'PQ-MLKEM768',
+      label: 'Post-Quantum KEM (FIPS 203 ML-KEM-768)',
+      kemType: 'pq',
+      curve: null,
+      pq: 'ML-KEM-768',
+      aead: 'AES-256-GCM',
+      kdf: 'HKDF-SHA256'
+    },
+    'CLASSICAL-ECDH-P256': {
+      id: 'CLASSICAL-ECDH-P256',
+      label: 'Classical Key Agreement (ECDH P-256)',
+      kemType: 'classical',
+      curve: 'P-256',
+      pq: null,
+      aead: 'AES-256-GCM',
+      kdf: 'HKDF-SHA256'
+    }
+  };
+
+  async function deriveAesGcmKeyFromSecrets({
+    classicalSecret,
+    pqSecret,
+    ephemeralPublicKey,
+    pqCiphertext,
+    keyId,
+    suiteId,
+    hkdfSalt
+  }) {
+    const ikmParts = [];
+    if (classicalSecret) ikmParts.push(classicalSecret);
+    if (pqSecret) ikmParts.push(pqSecret);
