+#include <cmath>
+#include <cstdint>
+#include <cstdlib>
+
+namespace {
+
+struct Vec {
+  double x, y, z;
+  constexpr Vec(double x_ = 0, double y_ = 0, double z_ = 0)
+      : x(x_), y(y_), z(z_) {}
+  Vec operator+(const Vec& b) const { return Vec(x + b.x, y + b.y, z + b.z); }
+  Vec operator-(const Vec& b) const { return Vec(x - b.x, y - b.y, z - b.z); }
+  Vec operator*(double b) const { return Vec(x * b, y * b, z * b); }
+  Vec mult(const Vec& b) const { return Vec(x * b.x, y * b.y, z * b.z); }
+  Vec& norm() {
+    return *this = *this * (1.0 / std::sqrt(x * x + y * y + z * z));
+  }
+  double dot(const Vec& b) const { return x * b.x + y * b.y + z * b.z; }
+  Vec operator%(const Vec& b) const {
+    return Vec(y * b.z - z * b.y, z * b.x - x * b.z, x * b.y - y * b.x);
+  }
+};
+
+struct Ray {
+  Vec o, d;
+  Ray(Vec o_, Vec d_) : o(o_), d(d_) {}
+};
+
+enum Refl_t { DIFF, SPEC, REFR };
+
+struct Sphere {
+  double rad;
+  Vec p, e, c;
+  Refl_t refl;
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_)
+      : rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray& r) const {
+    Vec op = p - r.o;
+    double t;
+    double eps = 1e-4;
+    double b = op.dot(r.d);
+    double det = b * b - op.dot(op) + rad * rad;
+    if (det < 0) return 0;
+    det = std::sqrt(det);
+    return (t = b - det) > eps ? t : ((t = b + det) > eps ? t : 0);
+  }
+};
+
+// Classic smallpt Cornell Box scene (mutable so sphere colors can be randomized)
+Sphere spheres[] = {
+    Sphere(1e5, Vec(1e5 + 1, 40.8, 81.6), Vec(), Vec(.75, .25, .25), DIFF),    // Left
+    Sphere(1e5, Vec(-1e5 + 99, 40.8, 81.6), Vec(), Vec(.25, .25, .75), DIFF),  // Rght
+    Sphere(1e5, Vec(50, 40.8, 1e5), Vec(), Vec(.75, .75, .75), DIFF),          // Back
+    Sphere(1e5, Vec(50, 40.8, -1e5 + 170), Vec(), Vec(), DIFF),                // Frnt
+    Sphere(1e5, Vec(50, 1e5, 81.6), Vec(), Vec(.75, .75, .75), DIFF),          // Botm
+    Sphere(1e5, Vec(50, -1e5 + 81.6, 81.6), Vec(), Vec(.75, .75, .75), DIFF),  // Top
+    Sphere(16.5, Vec(27, 16.5, 47), Vec(), Vec(1, 1, 1) * .999, SPEC),         // Mirr
+    Sphere(16.5, Vec(73, 16.5, 78), Vec(), Vec(1, 1, 1) * .999, REFR),         // Glas
+    Sphere(600, Vec(50, 681.6 - .27, 81.6), Vec(12, 12, 12), Vec(), DIFF)      // Lite
+};
+
+inline double clamp(double x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
+
+inline uint8_t toInt(double x) {
+  return static_cast<uint8_t>(std::pow(clamp(x), 1.0 / 2.2) * 255.0 + 0.5);
+}
+
+inline bool intersect(const Ray& r, double& t, int& id) {
+  double n = sizeof(spheres) / sizeof(Sphere);
+  double d;
+  double inf = t = 1e20;
+  for (int i = static_cast<int>(n); i--;) {
+    if ((d = spheres[i].intersect(r)) && d < t) {
+      t = d;
+      id = i;
+    }
+  }
+  return t < inf;
+}
+
+Vec radiance(const Ray& r_in, int depth_in, unsigned short* Xi) {
+  Ray r = r_in;
+  int depth = depth_in;
+  Vec acc(0, 0, 0);
+  Vec mask(1, 1, 1);
+
+  while (true) {
+    double t;
+    int id = 0;
+    if (!intersect(r, t, id)) {
+      return acc;
+    }
+    const Sphere& obj = spheres[id];
+    Vec x = r.o + r.d * t;
+    Vec n = (x - obj.p).norm();
+    Vec nl = n.dot(r.d) < 0 ? n : n * -1;
+    Vec f = obj.c;
+    double p = f.x > f.y && f.x > f.z ? f.x : f.y > f.z ? f.y : f.z;
+
+    acc = acc + mask.mult(obj.e);
+
+    if (++depth > 5) {
+      if (erand48(Xi) < p && p > 0) {
+        f = f * (1.0 / p);
+      } else {
+        return acc;
+      }
+    }
+    if (depth > 100) {
+      return acc;
+    }
+
+    if (obj.refl == DIFF) {
+      double r1 = 2.0 * M_PI * erand48(Xi);
+      double r2 = erand48(Xi);
+      double r2s = std::sqrt(r2);
+      Vec w = nl;
+      Vec u = ((std::fabs(w.x) > .1 ? Vec(0, 1) : Vec(1)) % w).norm();
+      Vec v = w % u;
+      Vec d = (u * std::cos(r1) * r2s + v * std::sin(r1) * r2s +
+               w * std::sqrt(1.0 - r2))
+                  .norm();
+      mask = mask.mult(f);
+      r = Ray(x, d);
+      continue;
+    } else if (obj.refl == SPEC) {
+      mask = mask.mult(f);
+      r = Ray(x, r.d - n * 2.0 * n.dot(r.d));
+      continue;
+    }
+
+    Ray reflRay(x, r.d - n * 2.0 * n.dot(r.d));
+    bool into = n.dot(nl) > 0;
+    double nc = 1.0;
+    double nt = 1.5;
+    double nnt = into ? nc / nt : nt / nc;
+    double ddn = r.d.dot(nl);
+    double cos2t = 1.0 - nnt * nnt * (1.0 - ddn * ddn);
+    if (cos2t < 0) {
+      mask = mask.mult(f);
+      r = reflRay;
+      continue;
+    }
+    Vec tdir =
+        (r.d * nnt - n * ((into ? 1 : -1) * (ddn * nnt + std::sqrt(cos2t))))
+            .norm();
+    double a = nt - nc;
+    double b = nt + nc;
+    double R0 = a * a / (b * b);
+    double c = 1.0 - (into ? -ddn : tdir.dot(n));
+    double Re = R0 + (1.0 - R0) * c * c * c * c * c;
+    double Tr = 1.0 - Re;
+    double P = .25 + .5 * Re;
+    double RP = Re / P;
+    double TP = Tr / (1.0 - P);
+
+    if (erand48(Xi) < P) {
+      mask = mask.mult(f) * RP;
+      r = reflRay;
+    } else {
+      mask = mask.mult(f) * TP;
+      r = Ray(x, tdir);
+    }
+  }
+}
+
+}  // namespace
+
+extern "C" {
+
+void set_sphere_color(int index, double r, double g, double b) {
+  int num_spheres = static_cast<int>(sizeof(spheres) / sizeof(Sphere));
+  if (index >= 0 && index < num_spheres) {
+    spheres[index].c = Vec(r, g, b);
+  }
+}
+
+void reset_default_colors() {
+  spheres[0].c = Vec(.75, .25, .25);          // Left wall
+  spheres[1].c = Vec(.25, .25, .75);          // Right wall
+  spheres[2].c = Vec(.75, .75, .75);          // Back wall
+  spheres[3].c = Vec(0, 0, 0);                // Front wall
+  spheres[4].c = Vec(.75, .75, .75);          // Bottom wall
+  spheres[5].c = Vec(.75, .75, .75);          // Top wall
+  spheres[6].c = Vec(1, 1, 1) * .999;         // Mirror sphere
+  spheres[7].c = Vec(1, 1, 1) * .999;         // Glass sphere
+}
+
+void render_frame(uint8_t* out_rgba, int w, int h, int samps, uint32_t seed) {
+  Ray cam(Vec(50, 52, 295.6), Vec(0, -0.042612, -1).norm());
+  Vec cx = Vec(w * .5135 / h);
+  Vec cy = (cx % cam.d).norm() * .5135;
+
+  int spp = samps > 0 ? samps : 1;
+
+  for (int y = 0; y < h; y++) {
+    unsigned short Xi[3] = {
+        static_cast<unsigned short>((y + seed) & 0xFFFF),
+        static_cast<unsigned short>((y * y + seed * 31) & 0xFFFF),
+        static_cast<unsigned short>((y * y * y + seed * 131) & 0xFFFF)};
+    for (int x = 0; x < w; x++) {
+      Vec c_pixel(0, 0, 0);
+      for (int sy = 0; sy < 2; sy++) {
+        for (int sx = 0; sx < 2; sx++) {
+          Vec r(0, 0, 0);
+          for (int s = 0; s < spp; s++) {
+            double r1 = 2.0 * erand48(Xi);
+            double dx = r1 < 1.0 ? std::sqrt(r1) - 1.0 : 1.0 - std::sqrt(2.0 - r1);
+            double r2 = 2.0 * erand48(Xi);
+            double dy = r2 < 1.0 ? std::sqrt(r2) - 1.0 : 1.0 - std::sqrt(2.0 - r2);
+            Vec d = cx * (((sx + .5 + dx) / 2.0 + x) / w - .5) +
+                    cy * (((sy + .5 + dy) / 2.0 + (h - y - 1)) / h - .5) + cam.d;
+            r = r + radiance(Ray(cam.o + d * 140.0, d.norm()), 0, Xi) * (1.0 / spp);
+          }
+          c_pixel = c_pixel + Vec(clamp(r.x), clamp(r.y), clamp(r.z)) * .25;
+        }
+      }
+      int idx = (y * w + x) * 4;
+      out_rgba[idx + 0] = toInt(c_pixel.x);
+      out_rgba[idx + 1] = toInt(c_pixel.y);
+      out_rgba[idx + 2] = toInt(c_pixel.z);
+      out_rgba[idx + 3] = 255;
+    }
+  }
+}
+
+}  // extern "C"
