+// smallpt, a Path Tracer by Kevin Beason, 2008
+// Adapted for WebAssembly (Emscripten) client-side execution with customizable sphere colors and progressive / chunked rendering.
+
+#include <math.h>
+#include <stdlib.h>
+#include <stdio.h>
+#include <stdint.h>
+#include <emscripten/emscripten.h>
+
+struct Vec {
+  double x, y, z;                  // position, also color (r,g,b)
+  Vec(double x_=0, double y_=0, double z_=0){ x=x_; y=y_; z=z_; }
+  Vec operator+(const Vec &b) const { return Vec(x+b.x,y+b.y,z+b.z); }
+  Vec operator-(const Vec &b) const { return Vec(x-b.x,y-b.y,z-b.z); }
+  Vec operator*(double b) const { return Vec(x*b,y*b,z*b); }
+  Vec mult(const Vec &b) const { return Vec(x*b.x,y*b.y,z*b.z); }
+  Vec& norm(){ return *this = *this * (1/sqrt(x*x+y*y+z*z)); }
+  double dot(const Vec &b) const { return x*b.x+y*b.y+z*b.z; } // cross:
+  Vec operator%(Vec&b){return Vec(y*b.z-z*b.y,z*b.x-x*b.z,x*b.y-y*b.x);}
+};
+
+struct Ray { Vec o, d; Ray(Vec o_, Vec d_) : o(o_), d(d_) {} };
+
+enum Refl_t { DIFF, SPEC, REFR };  // material types, used in radiance()
+
+struct Sphere {
+  double rad;       // radius
+  Vec p, e, c;      // position, emission, color
+  Refl_t refl;      // reflection type (DIFFuse, SPECular, REFRactive)
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_):
+    rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray &r) const { // returns distance, 0 if nohit
+    Vec op = p-r.o; // Solve t^2*d.d + 2*t*(o-p).d + (o-p).(o-p)-R^2 = 0
+    double t, eps=1e-4, b=op.dot(r.d), det=b*b-op.dot(op)+rad*rad;
+    if (det<0) return 0; else det=sqrt(det);
+    return (t=b-det)>eps ? t : ((t=b+det)>eps ? t : 0);
+  }
+};
+
+Sphere spheres[] = {//Scene: radius, position, emission, color, material
+  Sphere(1e5, Vec( 1e5+1,40.8,81.6), Vec(),Vec(.75,.25,.25),DIFF),//Left
+  Sphere(1e5, Vec(-1e5+99,40.8,81.6),Vec(),Vec(.25,.25,.75),DIFF),//Rght
+  Sphere(1e5, Vec(50,40.8, 1e5),     Vec(),Vec(.75,.75,.75),DIFF),//Back
+  Sphere(1e5, Vec(50,40.8,-1e5+170), Vec(),Vec(),           DIFF),//Frnt
+  Sphere(1e5, Vec(50, 1e5, 81.6),    Vec(),Vec(.75,.75,.75),DIFF),//Botm
+  Sphere(1e5, Vec(50,-1e5+81.6,81.6),Vec(),Vec(.75,.75,.75),DIFF),//Top
+  Sphere(16.5,Vec(27,16.5,47),       Vec(),Vec(1,1,1)*.999, SPEC),//Mirr
+  Sphere(16.5,Vec(73,16.5,78),       Vec(),Vec(1,1,1)*.999, REFR),//Glas
+  Sphere(600, Vec(50,681.6-.27,81.6),Vec(12,12,12),  Vec(), DIFF) //Lite
+};
+
+// Default colors backup so we can reset if needed
+const Vec default_colors[9] = {
+  Vec(.75,.25,.25),
+  Vec(.25,.25,.75),
+  Vec(.75,.75,.75),
+  Vec(0,0,0),
+  Vec(.75,.75,.75),
+  Vec(.75,.75,.75),
+  Vec(.999,.999,.999),
+  Vec(.999,.999,.999),
+  Vec(0,0,0)
+};
+
+inline double clamp(double x){ return x<0 ? 0 : x>1 ? 1 : x; }
+inline int toInt(double x){ return int(pow(clamp(x),1/2.2)*255+.5); }
+
+inline bool intersect(const Ray &r, double &t, int &id){
+  double n=sizeof(spheres)/sizeof(Sphere), d, inf=t=1e20;
+  for(int i=int(n);i--;) if((d=spheres[i].intersect(r))&&d<t){t=d;id=i;}
+  return t<inf;
+}
+
+Vec radiance(const Ray &r, int depth, unsigned short *Xi){
+  double t;                               // distance to intersection
+  int id=0;                               // id of intersected sphere
+  if (!intersect(r, t, id)) return Vec(); // if miss, return black
+  const Sphere &obj = spheres[id];        // the hit object
+  Vec x=r.o+r.d*t, n=(x-obj.p).norm(), nl=n.dot(r.d)<0?n:n*-1, f=obj.c;
+  double p = f.x>f.y && f.x>f.z ? f.x : f.y>f.z ? f.y : f.z; // max refl
+  if (++depth>5) {
+    if (erand48(Xi)<p && depth<100) f=f*(1/p);
+    else return obj.e; //R.R.
+  }
+  if (obj.refl == DIFF){                  // Ideal DIFFUSE reflection
+    double r1=2*M_PI*erand48(Xi), r2=erand48(Xi), r2s=sqrt(r2);
+    Vec w=nl, u=((fabs(w.x)>.1?Vec(0,1):Vec(1))%w).norm(), v=w%u;
+    Vec d = (u*cos(r1)*r2s + v*sin(r1)*r2s + w*sqrt(1-r2)).norm();
+    return obj.e + f.mult(radiance(Ray(x,d),depth,Xi));
+  } else if (obj.refl == SPEC)            // Ideal SPECULAR reflection
+    return obj.e + f.mult(radiance(Ray(x,r.d-n*2*n.dot(r.d)),depth,Xi));
+  Ray reflRay(x, r.d-n*2*n.dot(r.d));     // Ideal dielectric REFRACTION
+  bool into = n.dot(nl)>0;                // Ray from outside going in?
+  double nc=1, nt=1.5, nnt=into?nc/nt:nt/nc, ddn=r.d.dot(nl), cos2t;
+  if ((cos2t=1-nnt*nnt*(1-ddn*ddn))<0)    // Total internal reflection
+    return obj.e + f.mult(radiance(reflRay,depth,Xi));
+  Vec tdir = (r.d*nnt - n*((into?1:-1)*(ddn*nnt+sqrt(cos2t)))).norm();
+  double a=nt-nc, b=nt+nc, R0=a*a/(b*b), c = 1-(into?-ddn:tdir.dot(n));
+  double Re=R0+(1-R0)*c*c*c*c*c,Tr=1-Re,P=.25+.5*Re,RP=Re/P,TP=Tr/(1-P);
+  return obj.e + f.mult(depth>2 ? (erand48(Xi)<P ?   // Russian roulette
+    radiance(reflRay,depth,Xi)*RP:radiance(Ray(x,tdir),depth,Xi)*TP) :
+    radiance(reflRay,depth,Xi)*Re+radiance(Ray(x,tdir),depth,Xi)*Tr);
+}
+
+static int g_w = 0;
+static int g_h = 0;
+static Vec *g_accum = NULL;
+static uint8_t *g_rgba = NULL;
+static int g_total_samples = 0;
+
+extern "C" {
+
+EMSCRIPTEN_KEEPALIVE
+int get_sphere_count() {
+  return sizeof(spheres) / sizeof(Sphere);
+}
+
+EMSCRIPTEN_KEEPALIVE
+void set_sphere_color(int idx, double r, double g, double b) {
+  int n = get_sphere_count();
+  if (idx >= 0 && idx < n) {
+    spheres[idx].c = Vec(r, g, b);
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+double get_sphere_color_r(int idx) {
+  return (idx >= 0 && idx < get_sphere_count()) ? spheres[idx].c.x : 0.0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+double get_sphere_color_g(int idx) {
+  return (idx >= 0 && idx < get_sphere_count()) ? spheres[idx].c.y : 0.0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+double get_sphere_color_b(int idx) {
+  return (idx >= 0 && idx < get_sphere_count()) ? spheres[idx].c.z : 0.0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+void reset_default_colors() {
+  for (int i = 0; i < 9; i++) {
+    spheres[i].c = default_colors[i];
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+void randomize_sphere_colors(unsigned int seed) {
+  unsigned short Xi[3] = {
+    (unsigned short)(seed & 0xFFFF),
+    (unsigned short)((seed >> 16) & 0xFFFF),
+    (unsigned short)((seed * 31337) & 0xFFFF)
+  };
+  // Randomize Left, Right, Back, Bottom, Top walls, plus Mirror and Glass tint!
+  // Indices: 0 (Left), 1 (Right), 2 (Back), 4 (Bottom), 5 (Top), 6 (Mirror), 7 (Glass)
+  int targets[] = {0, 1, 2, 4, 5, 6, 7};
+  for (int k = 0; k < 7; k++) {
+    int idx = targets[k];
+    if (idx == 6 || idx == 7) {
+      // Mirror and glass look great with bright pastel / jewel tints
+      double r = 0.55 + 0.449 * erand48(Xi);
+      double g = 0.55 + 0.449 * erand48(Xi);
+      double b = 0.55 + 0.449 * erand48(Xi);
+      spheres[idx].c = Vec(r, g, b);
+    } else {
+      // Diffuse walls: vibrant colors with good albedo (0.15 to 0.85)
+      double r = 0.15 + 0.70 * erand48(Xi);
+      double g = 0.15 + 0.70 * erand48(Xi);
+      double b = 0.15 + 0.70 * erand48(Xi);
+      spheres[idx].c = Vec(r, g, b);
+    }
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* init_render(int w, int h) {
+  if (g_w != w || g_h != h || !g_accum || !g_rgba) {
+    if (g_accum) free(g_accum);
+    if (g_rgba) free(g_rgba);
+    g_w = w;
+    g_h = h;
+    g_accum = (Vec*)malloc(sizeof(Vec) * w * h);
+    g_rgba = (uint8_t*)malloc(sizeof(uint8_t) * w * h * 4);
+  }
+  for (int i = 0; i < w * h; i++) {
+    g_accum[i] = Vec(0, 0, 0);
+    g_rgba[i * 4 + 0] = 0;
+    g_rgba[i * 4 + 1] = 0;
+    g_rgba[i * 4 + 2] = 0;
+    g_rgba[i * 4 + 3] = 255;
+  }
+  g_total_samples = 0;
+  return g_rgba;
+}
+
+// Render a batch of rows for progressive rendering or full image rendering.
+// Each call to render_rows traces `samps_per_subpixel` samples for each of the 2x2 subpixels
+// (so 4 * samps_per_subpixel total samples per pixel in the row range [start_y, end_y)).
+// Wait: if we do progressive passes over the full image, or row-by-row for a fixed sample count,
+// let's support both!
+// In `render_rows(start_y, end_y, samps, pass_index)`:
+// Accumulates `samps` samples per subpixel (4 * samps rays per pixel) into g_accum for rows [start_y, end_y),
+// and updates g_rgba assuming `total_passes` completed so far for those rows is `pass_index + 1`.
+EMSCRIPTEN_KEEPALIVE
+void render_rows(int start_y, int end_y, int samps, int pass_index) {
+  if (!g_accum || !g_rgba || g_w <= 0 || g_h <= 0) return;
+  int w = g_w;
+  int h = g_h;
+  if (start_y < 0) start_y = 0;
+  if (end_y > h) end_y = h;
+  if (samps < 1) samps = 1;
+
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135, r;
+
+  double weight = 1.0 / (double)(pass_index + 1);
+  double prev_weight = (double)pass_index / (double)(pass_index + 1);
+
+  for (int y = start_y; y < end_y; y++) {
+    unsigned short Xi[3] = {
+      (unsigned short)(y + pass_index * 7919),
+      (unsigned short)(pass_index * 104729 + y * 31),
+      (unsigned short)(y * y * y + pass_index * 65537)
+    };
+    for (int x = 0; x < w; x++) {
+      int i = (h - y - 1) * w + x;
+      Vec pixel_rad(0, 0, 0);
+      for (int sy = 0; sy < 2; sy++) {     // 2x2 subpixel rows
+        for (int sx = 0; sx < 2; sx++) {   // 2x2 subpixel cols
+          r = Vec();
+          for (int s = 0; s < samps; s++) {
+            double r1 = 2 * erand48(Xi), dx = r1 < 1 ? sqrt(r1) - 1 : 1 - sqrt(2 - r1);
+            double r2 = 2 * erand48(Xi), dy = r2 < 1 ? sqrt(r2) - 1 : 1 - sqrt(2 - r2);
+            Vec d = cx * (((sx + .5 + dx) / 2 + x) / w - .5) +
+                    cy * (((sy + .5 + dy) / 2 + y) / h - .5) + cam.d;
+            r = r + radiance(Ray(cam.o + d * 140, d.norm()), 0, Xi) * (1. / samps);
+          }
+          pixel_rad = pixel_rad + Vec(clamp(r.x), clamp(r.y), clamp(r.z)) * .25;
+        }
+      }
+      g_accum[i] = g_accum[i] * prev_weight + pixel_rad * weight;
+      g_rgba[i * 4 + 0] = toInt(g_accum[i].x);
+      g_rgba[i * 4 + 1] = toInt(g_accum[i].y);
+      g_rgba[i * 4 + 2] = toInt(g_accum[i].z);
+      g_rgba[i * 4 + 3] = 255;
+    }
+  }
+}
+
+// Single-call synchronous render for convenience
+EMSCRIPTEN_KEEPALIVE
+uint8_t* render(int w, int h, int samps) {
+  init_render(w, h);
+  render_rows(0, h, samps, 0);
+  return g_rgba;
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* get_rgba_ptr() {
+  return g_rgba;
+}
+
+}
