+// smallpt, a Path Tracer by Kevin Beason, 2008
+// Compiled to WebAssembly via Emscripten for client-side browser execution.
+
+#include <math.h>
+#include <stdlib.h>
+#include <stdio.h>
+#include <stdint.h>
+#include <vector>
+
+#ifdef __EMSCRIPTEN__
+#include <emscripten/emscripten.h>
+#else
+#define EMSCRIPTEN_KEEPALIVE
+#endif
+
+struct Vec {        // Usage: time ./smallpt 5000 && xv image.ppm
+  double x, y, z;                  // position, also color (r,g,b)
+  Vec(double x_=0, double y_=0, double z_=0){ x=x_; y=y_; z=z_; }
+  Vec operator+(const Vec &b) const { return Vec(x+b.x,y+b.y,z+b.z); }
+  Vec operator-(const Vec &b) const { return Vec(x-b.x,y-b.y,z-b.z); }
+  Vec operator*(double b) const { return Vec(x*b,y*b,z*b); }
+  Vec mult(const Vec &b) const { return Vec(x*b.x,y*b.y,z*b.z); }
+  Vec& norm(){ return *this = *this * (1/sqrt(x*x+y*y+z*z)); }
+  double dot(const Vec &b) const { return x*b.x+y*b.y+z*b.z; } // cross:
+  Vec operator%(Vec&b){return Vec(y*b.z-z*b.y,z*b.x-x*b.z,x*b.y-y*b.x);}
+};
+
+struct Ray { Vec o, d; Ray(Vec o_, Vec d_) : o(o_), d(d_) {} };
+
+enum Refl_t { DIFF, SPEC, REFR };  // material types, used in radiance()
+
+struct Sphere {
+  double rad;       // radius
+  Vec p, e, c;      // position, emission, color
+  Refl_t refl;      // reflection type (DIFFuse, SPECular, REFRactive)
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_):
+    rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray &r) const { // returns distance, 0 if nohit
+    Vec op = p-r.o; // Solve t^2*d.d + 2*t*(o-p).d + (o-p).(o-p)-R^2 = 0
+    double t, eps=1e-4, b=op.dot(r.d), det=b*b-op.dot(op)+rad*rad;
+    if (det<0) return 0; else det=sqrt(det);
+    return (t=b-det)>eps ? t : ((t=b+det)>eps ? t : 0);
+  }
+};
+
+Sphere spheres[] = {//Scene: radius, position, emission, color, material
+  Sphere(1e5, Vec( 1e5+1,40.8,81.6), Vec(),Vec(.75,.25,.25),DIFF),//Left
+  Sphere(1e5, Vec(-1e5+99,40.8,81.6),Vec(),Vec(.25,.25,.75),DIFF),//Rght
+  Sphere(1e5, Vec(50,40.8, 1e5),     Vec(),Vec(.75,.75,.75),DIFF),//Back
+  Sphere(1e5, Vec(50,40.8,-1e5+170), Vec(),Vec(),           DIFF),//Frnt
+  Sphere(1e5, Vec(50, 1e5, 81.6),    Vec(),Vec(.75,.75,.75),DIFF),//Botm
+  Sphere(1e5, Vec(50,-1e5+81.6,81.6),Vec(),Vec(.75,.75,.75),DIFF),//Top
+  Sphere(16.5,Vec(27,16.5,47),       Vec(),Vec(1,1,1)*.999, SPEC),//Mirr
+  Sphere(16.5,Vec(73,16.5,78),       Vec(),Vec(1,1,1)*.999, REFR),//Glas
+  Sphere(600, Vec(50,681.6-.27,81.6),Vec(12,12,12),  Vec(), DIFF) //Lite
+};
+
+const Vec default_colors[] = {
+  Vec(.75,.25,.25),
+  Vec(.25,.25,.75),
+  Vec(.75,.75,.75),
+  Vec(0,0,0),
+  Vec(.75,.75,.75),
+  Vec(.75,.75,.75),
+  Vec(1,1,1)*.999,
+  Vec(1,1,1)*.999,
+  Vec(0,0,0)
+};
+
+inline double clamp(double x){ return x<0 ? 0 : x>1 ? 1 : x; }
+inline int toInt(double x){ return int(pow(clamp(x),1/2.2)*255+.5); }
+inline bool intersect(const Ray &r, double &t, int &id){
+  double n=sizeof(spheres)/sizeof(Sphere), d, inf=t=1e20;
+  for(int i=int(n);i--;) if((d=spheres[i].intersect(r))&&d<t){t=d;id=i;}
+  return t<inf;
+}
+
+Vec radiance(const Ray &r, int depth, unsigned short *Xi){
+  double t;                               // distance to intersection
+  int id=0;                               // id of intersected object
+  if (!intersect(r, t, id)) return Vec(); // if miss, return black
+  const Sphere &obj = spheres[id];        // the hit object
+  Vec x=r.o+r.d*t, n=(x-obj.p).norm(), nl=n.dot(r.d)<0?n:n*-1, f=obj.c;
+  double p = f.x>f.y && f.x>f.z ? f.x : f.y>f.z ? f.y : f.z; // max refl
+  if (++depth>5) {
+    if (erand48(Xi)<p && depth<64) f=f*(1/p);
+    else return obj.e; // R.R.
+  }
+  if (obj.refl == DIFF){                  // Ideal DIFFUSE reflection
+    double r1=2*M_PI*erand48(Xi), r2=erand48(Xi), r2s=sqrt(r2);
+    Vec w=nl, u=((fabs(w.x)>.1?Vec(0,1):Vec(1))%w).norm(), v=w%u;
+    Vec d = (u*cos(r1)*r2s + v*sin(r1)*r2s + w*sqrt(1-r2)).norm();
+    return obj.e + f.mult(radiance(Ray(x,d),depth,Xi));
+  } else if (obj.refl == SPEC)            // Ideal SPECULAR reflection
+    return obj.e + f.mult(radiance(Ray(x,r.d-n*2*n.dot(r.d)),depth,Xi));
+  Ray reflRay(x, r.d-n*2*n.dot(r.d));     // Ideal dielectric REFRACTION
+  bool into = n.dot(nl)>0;                // Ray from outside going in?
+  double nc=1, nt=1.5, nnt=into?nc/nt:nt/nc, ddn=r.d.dot(nl), cos2t;
+  if ((cos2t=1-nnt*nnt*(1-ddn*ddn))<0)    // Total internal reflection
+    return obj.e + f.mult(radiance(reflRay,depth,Xi));
+  Vec tdir = (r.d*nnt - n*((into?1:-1)*(ddn*nnt+sqrt(cos2t)))).norm();
+  double a=nt-nc, b=nt+nc, R0=a*a/(b*b), c = 1-(into?-ddn:tdir.dot(n));
+  double Re=R0+(1-R0)*c*c*c*c*c,Tr=1-Re,P=.25+.5*Re,RP=Re/P,TP=Tr/(1-P);
+  return obj.e + f.mult(depth>2 ? (erand48(Xi)<P ?   // Russian roulette
+    radiance(reflRay,depth,Xi)*RP:radiance(Ray(x,tdir),depth,Xi)*TP) :
+    radiance(reflRay,depth,Xi)*Re+radiance(Ray(x,tdir),depth,Xi)*Tr);
+}
+
+static double hue2rgb(double p, double q, double t) {
+  if (t < 0.0) t += 1.0;
+  if (t > 1.0) t -= 1.0;
+  if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
+  if (t < 1.0/2.0) return q;
+  if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
+  return p;
+}
+
+static Vec hsl_to_rgb(double h, double s, double l) {
+  h = h - floor(h);
+  double q = l < 0.5 ? l * (1.0 + s) : l + s - l * s;
+  double p = 2.0 * l - q;
+  return Vec(
+    hue2rgb(p, q, h + 1.0/3.0),
+    hue2rgb(p, q, h),
+    hue2rgb(p, q, h - 1.0/3.0)
+  );
+}
+
+static uint64_t splitmix64_next(uint64_t &state) {
+  uint64_t z = (state += 0x9E3779B97F4A7C15ULL);
+  z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
+  z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
+  return z ^ (z >> 31);
+}
+
+static double rand01(uint64_t &state) {
+  return (splitmix64_next(state) >> 11) * (1.0 / 9007199254740992.0);
+}
+
+static uint64_t randomize_call_count = 0;
+static double last_base_hue = 0.0;
+
+static std::vector<uint8_t> pixel_buffer;
+static std::vector<double> accum_buffer;
+static int accum_w = 0;
+static int accum_h = 0;
+static int accum_passes = 0;
+
+extern "C" {
+
+EMSCRIPTEN_KEEPALIVE
+int get_num_spheres() {
+  return int(sizeof(spheres) / sizeof(Sphere));
+}
+
+EMSCRIPTEN_KEEPALIVE
+void reset_sphere_colors() {
+  int n = get_num_spheres();
+  for (int i = 0; i < n; i++) {
+    spheres[i].c = default_colors[i];
+  }
+  accum_passes = 0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+void set_sphere_color(int index, double r, double g, double b) {
+  int n = get_num_spheres();
+  if (index >= 0 && index < n) {
+    spheres[index].c = Vec(clamp(r), clamp(g), clamp(b));
+    accum_passes = 0;
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+double get_sphere_color_r(int index) {
+  int n = get_num_spheres();
+  return (index >= 0 && index < n) ? spheres[index].c.x : 0.0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+double get_sphere_color_g(int index) {
+  int n = get_num_spheres();
+  return (index >= 0 && index < n) ? spheres[index].c.y : 0.0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+double get_sphere_color_b(int index) {
+  int n = get_num_spheres();
+  return (index >= 0 && index < n) ? spheres[index].c.z : 0.0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+void randomize_sphere_colors(unsigned int seed) {
+  randomize_call_count += 1;
+  uint64_t state = ((uint64_t)seed * 0xBF58476D1CE4E5B9ULL) ^ (randomize_call_count * 0x9E3779B97F4A7C15ULL);
+  for (int i = 0; i < 4; i++) splitmix64_next(state);
+
+  // Base hue for Left wall (0) guaranteed to shift significantly each time, and contrasting hue for Right wall (1)
+  double base_hue = last_base_hue + 0.25 + 0.50 * rand01(state);
+  base_hue = base_hue - floor(base_hue);
+  last_base_hue = base_hue;
+
+  spheres[0].c = hsl_to_rgb(base_hue, 0.72 + 0.23 * rand01(state), 0.46 + 0.14 * rand01(state));
+  spheres[1].c = hsl_to_rgb(base_hue + 0.35 + 0.30 * rand01(state), 0.72 + 0.23 * rand01(state), 0.46 + 0.14 * rand01(state));
+
+  // Back wall (2), Floor (4), Ceiling (5)
+  spheres[2].c = hsl_to_rgb(rand01(state), 0.58 + 0.32 * rand01(state), 0.54 + 0.18 * rand01(state));
+  spheres[4].c = hsl_to_rgb(rand01(state), 0.48 + 0.35 * rand01(state), 0.54 + 0.18 * rand01(state));
+  spheres[5].c = hsl_to_rgb(rand01(state), 0.42 + 0.35 * rand01(state), 0.62 + 0.18 * rand01(state));
+
+  // Mirror sphere (6) and Glass sphere (7) - vivid reflective/refractive tints
+  double sphere_hue = rand01(state);
+  spheres[6].c = hsl_to_rgb(sphere_hue, 0.78 + 0.20 * rand01(state), 0.65 + 0.18 * rand01(state));
+  spheres[7].c = hsl_to_rgb(sphere_hue + 0.42 + 0.20 * rand01(state), 0.78 + 0.20 * rand01(state), 0.68 + 0.18 * rand01(state));
+
+  accum_passes = 0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+void reset_accumulation(int w, int h) {
+  accum_w = w;
+  accum_h = h;
+  accum_passes = 0;
+  accum_buffer.assign(w * h * 3, 0.0);
+  pixel_buffer.resize(w * h * 4);
+}
+
+// Renders `samps` samples per subpixel (2x2 subpixels per pixel) and accumulates
+// into the progressive buffer so each pass refines the image.
+EMSCRIPTEN_KEEPALIVE
+uint8_t* render_pass(int w, int h, int samps_per_subpixel, unsigned int seed_offset) {
+  if (w != accum_w || h != accum_h || (int)accum_buffer.size() != w * h * 3) {
+    reset_accumulation(w, h);
+  }
+  if (samps_per_subpixel < 1) samps_per_subpixel = 1;
+
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135, r;
+
+  for (int y=0; y<h; y++) {                       // Loop over image rows
+    for (int x=0; x<w; x++) {                     // Loop cols
+      int idx = (h-y-1)*w+x;
+      Vec pixel_radiance(0, 0, 0);
+      for (int sy=0; sy<2; sy++) {                // 2x2 subpixel rows
+        for (int sx=0; sx<2; sx++, r=Vec()) {     // 2x2 subpixel cols
+          unsigned short Xi[3] = {
+            (unsigned short)(y + seed_offset * 131 + sy * 17),
+            (unsigned short)(x + seed_offset * 977 + sx * 31),
+            (unsigned short)(y * x + seed_offset * 3571 + accum_passes * 613)
+          };
+          for (int s=0; s<samps_per_subpixel; s++) {
+            double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+            double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+            Vec d = cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                    cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+            r = r + radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*(1./samps_per_subpixel);
+          }
+          pixel_radiance = pixel_radiance + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+        }
+      }
+      accum_buffer[idx * 3 + 0] += pixel_radiance.x;
+      accum_buffer[idx * 3 + 1] += pixel_radiance.y;
+      accum_buffer[idx * 3 + 2] += pixel_radiance.z;
+    }
+  }
+
+  accum_passes += 1;
+  double inv_passes = 1.0 / double(accum_passes);
+  for (int i = 0; i < w * h; i++) {
+    pixel_buffer[i * 4 + 0] = (uint8_t)toInt(accum_buffer[i * 3 + 0] * inv_passes);
+    pixel_buffer[i * 4 + 1] = (uint8_t)toInt(accum_buffer[i * 3 + 1] * inv_passes);
+    pixel_buffer[i * 4 + 2] = (uint8_t)toInt(accum_buffer[i * 3 + 2] * inv_passes);
+    pixel_buffer[i * 4 + 3] = 255;
+  }
+
+  return pixel_buffer.data();
+}
+
+// Single-call render from scratch for a given width, height, and samples per pixel
+EMSCRIPTEN_KEEPALIVE
+uint8_t* render_smallpt(int w, int h, int total_samples) {
+  reset_accumulation(w, h);
+  int samps = total_samples / 4;
+  if (samps < 1) samps = 1;
+  return render_pass(w, h, samps, 1);
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* get_pixel_buffer() {
+  return pixel_buffer.data();
+}
+
+EMSCRIPTEN_KEEPALIVE
+int get_accum_passes() {
+  return accum_passes;
+}
+
+} // extern "C"
