+const MainSectionSpa: React.FC<MainSectionSpaProps> = ({
+  baseUrl,
+  topStories,
+  topArticle,
+  topNewsArticles,
+  worldNewsArticles,
+  politicsArticles,
+  multimediaItems,
+  reportItems,
+  initialSection = 'top-news',
+}) => {
+  const [activeSection, setActiveSection] = useState<SectionId>(initialSection);
+
+  const navigateToSection = (sectionId: SectionId, updateHistory = true) => {
+    startTransition(() => {
+      setActiveSection(sectionId);
+    });
+
+    if (typeof window !== 'undefined') {
+      const sectionMeta = MAIN_SECTIONS.find((s) => s.id === sectionId);
+      if (sectionMeta) {
+        document.title =
+          sectionId === 'top-news'
+            ? 'The DevTools Times'
+            : `${sectionMeta.label} | The DevTools Times`;
+      }
+
+      if (updateHistory) {
+        const nextUrl = buildSectionUrl(baseUrl, sectionId);
+        if (window.location.pathname + window.location.search !== nextUrl) {
+          window.history.pushState(null, '', nextUrl);
+        }
+      }
+    }
+  };
+
+  useEffect(() => {
+    const resolved = resolveSectionFromLocation(initialSection);
+    if (resolved !== activeSection) {
+      startTransition(() => {
+        setActiveSection(resolved);
+      });
+    }
+
+    // Ensure history state is null so Astro's ClientRouter does not trigger full-page swaps on popstate
+    window.history.replaceState(null, '', window.location.href);
+
+    const handlePopState = () => {
+      const nextSection = resolveSectionFromLocation('top-news');
+      startTransition(() => {
+        setActiveSection(nextSection);
+      });
+    };
+
+    const handleCustomNavigate = (event: Event) => {
+      const customEvent = event as CustomEvent<{ section?: SectionId }>;
+      const targetSection = customEvent.detail?.section;
+      if (targetSection) {
+        navigateToSection(targetSection, true);
+      }
+    };
+
+    (window as any).__devtoolsTimesNavigate = (sectionId: SectionId) => {
+      navigateToSection(sectionId, true);
+    };
+
+    window.addEventListener('popstate', handlePopState);
+    window.addEventListener('devtools-times:navigate', handleCustomNavigate);
+
+    return () => {
+      delete (window as any).__devtoolsTimesNavigate;
+      window.removeEventListener('popstate', handlePopState);
+      window.removeEventListener('devtools-times:navigate', handleCustomNavigate);
+    };
+  }, []);
+
+  return (
+    <div>
+      {/* Main Section SPA Navigation Bar */}
+      <nav
+        aria-label="Main sections"
+        data-section-nav="true"
+        className="bg-gray-50 border-b border-gray-300 sticky top-0 z-20"
+      >
+        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
+          <div className="flex items-center justify-center space-x-2 sm:space-x-6 py-2.5 overflow-x-auto text-sm font-semibold">
+            {MAIN_SECTIONS.map((section) => {
+              const isActive = activeSection === section.id;
+              return (
+                <button
+                  key={section.id}
+                  id={`section-tab-${section.id}`}
+                  type="button"
+                  aria-current={isActive ? 'page' : undefined}
+                  aria-controls={`section-view-${section.id}`}
+                  data-section-tab={section.id}
+                  data-active={isActive ? 'true' : 'false'}
+                  onClick={() => navigateToSection(section.id)}
+                  className={`px-3.5 py-1.5 rounded-md whitespace-nowrap transition-colors cursor-pointer ${
+                    isActive
+                      ? 'bg-gray-900 text-amber-400 font-bold shadow-xs'
+                      : 'text-gray-700 hover:text-gray-900 hover:bg-gray-200'
+                  }`}
+                >
+                  {section.label}
+                </button>
+              );
+            })}
+          </div>
+        </div>
+      </nav>
+
+      {/* Top News View (preserved offscreen with React Activity) */}
+      <Activity mode={activeSection === 'top-news' ? 'visible' : 'hidden'} name="Top News">
+        <div
+          id="section-view-top-news"
+          data-section-view="top-news"
+          data-active={activeSection === 'top-news' ? 'true' : 'false'}
+          className="section-view"
+        >
+          {/* Top Stories Bar */}
+          <div className="bg-white border-b border-gray-300">
+            <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
+              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
+                {topStories.map((article) => (
+                  <div
+                    key={article.id}
+                    className="border-l border-gray-300 pl-4 first:border-l-0 first:pl-0"
+                  >
+                    <a href={`${baseUrl}articles/${article.id}`}>
+                      <h3 className="font-bold text-gray-900 hover:text-amber-400 cursor-pointer">
+                        {article.title}
+                      </h3>
+                    </a>
+                    <span className="text-xs text-gray-500">{article.dateFormatted}</span>
+                  </div>
+                ))}
+              </div>
+            </div>
+          </div>
+
+          {/* Lead Story */}
+          <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-6 mt-6">
+            <LargeArticleTeaser article={topArticle} baseUrl={baseUrl} />
+          </div>
+
+          <div className="divide-y divide-gray-200 max-w-6xl mx-auto">
+            <section className="p-4 md:p-6 text-center">
+              <AdSlotBanner />
+            </section>
+
+            {/* "Top News" section with the new grid variant */}
+            <TopStoryTeaserGridView
+              title="Top News"
+              articles={topNewsArticles}
+              baseUrl={baseUrl}
+            />
+          </div>
+        </div>
+      </Activity>
+
+      {/* World View (preserved offscreen with React Activity) */}
+      <Activity mode={activeSection === 'world' ? 'visible' : 'hidden'} name="World">
+        <div
+          id="section-view-world"
+          data-section-view="world"
+          data-active={activeSection === 'world' ? 'true' : 'false'}
+          className="section-view divide-y divide-gray-200 max-w-6xl mx-auto"
+        >
+          <SimpleTeaserGridView title="World" articles={worldNewsArticles} baseUrl={baseUrl} />
+
+          <section className="p-4 md:p-6 text-center">
+            <AdSlotBanner />
+          </section>
+        </div>
+      </Activity>
+
+      {/* Politics View (preserved offscreen with React Activity) */}
+      <Activity mode={activeSection === 'politics' ? 'visible' : 'hidden'} name="Politics">
+        <div
+          id="section-view-politics"
+          data-section-view="politics"
+          data-active={activeSection === 'politics' ? 'true' : 'false'}
+          className="section-view divide-y divide-gray-200 max-w-6xl mx-auto"
+        >
+          {/* "Politics" section with the new grid variant */}
+          <TopStoryTeaserGridView
+            title="Politics"
+            articles={politicsArticles}
+            baseUrl={baseUrl}
+          />
+
+          <section className="p-4 md:p-6 text-center">
+            <AdSlotBanner />
+          </section>
+        </div>
+      </Activity>
+
+      {/* Multimedia View (preserved offscreen with React Activity) */}
+      <Activity mode={activeSection === 'multimedia' ? 'visible' : 'hidden'} name="Multimedia">
+        <div
+          id="section-view-multimedia"
+          data-section-view="multimedia"
+          data-active={activeSection === 'multimedia' ? 'true' : 'false'}
+          className="section-view max-w-6xl mx-auto"
+        >
+          <MultimediaSectionView items={multimediaItems} baseUrl={baseUrl} />
+        </div>
+      </Activity>
+
+      {/* Reports View (preserved offscreen with React Activity) */}
+      <Activity mode={activeSection === 'reports' ? 'visible' : 'hidden'} name="Reports">
+        <div
+          id="section-view-reports"
+          data-section-view="reports"
+          data-active={activeSection === 'reports' ? 'true' : 'false'}
+          className="section-view max-w-6xl mx-auto"
+        >
+          <ReportsSectionView items={reportItems} baseUrl={baseUrl} />
+        </div>
+      </Activity>
+    </div>
+  );
+};
+
+export default MainSectionSpa;
