+      id: article.id,
+      title: article.data.title,
+      dateFormatted: article.data.date.toLocaleDateString(),
+    })),
+    topArticle,
+    topNewsArticles,
+    worldNewsArticles,
+    politicsArticles,
+    multimediaItems,
+    reportItems,
+  };
