+      const passwordInput = document.getElementById('new-password');
+      const togglePasswordBtn = document.getElementById('toggle-password');
+      const togglePasswordText = document.getElementById('toggle-password-text');
+      if (passwordInput && togglePasswordBtn && togglePasswordText) {
+        togglePasswordBtn.addEventListener('click', () => {
+          const isShowing = passwordInput.type === 'text';
+          passwordInput.type = isShowing ? 'password' : 'text';
+          togglePasswordBtn.setAttribute('aria-pressed', String(!isShowing));
+          togglePasswordBtn.setAttribute('aria-label', isShowing ? 'Show password' : 'Hide password');
+          togglePasswordText.textContent = isShowing ? 'Show' : 'Hide';
+        });
+      }
+
+      // Multi-Step Navigation & Progress Management
+      const steps = Array.from(form.querySelectorAll('.form-step'));
+      const indicators = Array.from(document.querySelectorAll('[data-step-indicator]'));
+      const progressBar = document.getElementById('registration-progress');
+      let currentStep = 1;
+
+      const stepNames = {
+        1: 'Step 1: Account',
+        2: 'Step 2: Contact & Address',
+        3: 'Step 3: Preferences'
+      };
+
+      const updateReviewSummary = () => {
+        const fullName = document.getElementById('full-name')?.value.trim() || '—';
+        const email = document.getElementById('email')?.value.trim() || '—';
+        const phone = document.getElementById('phone')?.value.trim() || '—';
+        const street = document.getElementById('street-address')?.value.trim() || '';
+        const city = document.getElementById('city')?.value.trim() || '';
+        const postal = document.getElementById('postal-code')?.value.trim() || '';
+        const addressParts = [street, city, postal].filter(Boolean);
+
+        // Always use textContent to prevent XSS injection
+        document.getElementById('review-name').textContent = fullName;
+        document.getElementById('review-email').textContent = email;
+        document.getElementById('review-phone').textContent = phone;
+        document.getElementById('review-address').textContent = addressParts.length ? addressParts.join(', ') : '—';
+      };
+
+      const validateStep = (stepNumber) => {
+        const stepFieldset = form.querySelector(`.form-step[data-step="${stepNumber}"]`);
+        if (!stepFieldset) return true;
+        const fields = Array.from(stepFieldset.querySelectorAll('input, select, textarea')).filter(
+          (el) => el.type !== 'hidden'
+        );
+
+        let firstInvalid = null;
+        for (const field of fields) {
+          const valid = markFieldInteractedAndValidate(field, false);
+          if (!valid && !firstInvalid) {
+            firstInvalid = field;
+          }
+        }
+
+        if (firstInvalid) {
+          firstInvalid.focus();
+          announceError(firstInvalid);
+          return false;
+        }
+        return true;
+      };
+
+      const goToStep = (targetStep) => {
+        currentStep = targetStep;
+
+        steps.forEach((stepEl) => {
+          const stepNum = Number(stepEl.dataset.step);
+          const isActive = stepNum === targetStep;
+          stepEl.hidden = !isActive;
+          stepEl.toggleAttribute('inert', !isActive);
+        });
+
+        indicators.forEach((indEl) => {
+          const stepNum = Number(indEl.dataset.stepIndicator);
+          const labelSpan = indEl.querySelector('.step-label');
+          if (stepNum < targetStep) {
+            indEl.removeAttribute('aria-current');
+            indEl.classList.add('step-done');
+            if (labelSpan) labelSpan.textContent = `${stepNames[stepNum]} (completed)`;
+          } else if (stepNum === targetStep) {
+            indEl.setAttribute('aria-current', 'step');
+            indEl.classList.remove('step-done');
+            if (labelSpan) labelSpan.textContent = stepNames[stepNum];
+          } else {
+            indEl.removeAttribute('aria-current');
+            indEl.classList.remove('step-done');
+            if (labelSpan) labelSpan.textContent = stepNames[stepNum];
+          }
+        });
+
+        if (progressBar) {
+          progressBar.value = targetStep;
+          progressBar.textContent = `Step ${targetStep} of ${steps.length}`;
+        }
+
+        if (targetStep === 3) {
+          updateReviewSummary();
+        }
+
+        const activeHeading = document.getElementById(`step-${targetStep}-heading`);
+        if (activeHeading) {
+          activeHeading.focus();
+        }
+      };
+
+      // Wire Next and Previous step buttons
+      form.querySelectorAll('[data-next-step]').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          const nextStep = Number(btn.dataset.nextStep);
+          if (validateStep(currentStep)) {
+            goToStep(nextStep);
+          }
+        });
+      });
+
+      form.querySelectorAll('[data-prev-step]').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          const prevStep = Number(btn.dataset.prevStep);
+          goToStep(prevStep);
+        });
+      });
+
+      // IME-safe Enter key handling for multi-step progression
+      form.addEventListener('keydown', (e) => {
+        if (e.key !== 'Enter' || e.isComposing) return;
+        const target = e.target;
+        if (!target.matches?.('input, select')) return;
+        if (target.type === 'submit' || target.type === 'button') return;
+
+        if (currentStep < steps.length) {
+          e.preventDefault();
+          if (validateStep(currentStep)) {
+            goToStep(currentStep + 1);
+          }
+        }
+      });
+
+      // Final Form Submission
+      const submitBtn = document.getElementById('submit-rewards-btn');
+      const statusBanner = document.getElementById('rewards-submission-status');
+
+      form.addEventListener('submit', (e) => {
+        e.preventDefault();
+
+        // Check anti-spam honeypot
+        const honeypot = document.getElementById('bot-trap-website');
+        if (honeypot && honeypot.value.trim() !== '') {
+          return;
+        }
+
+        // Validate all steps sequentially
+        for (let stepNum = 1; stepNum <= steps.length; stepNum++) {
+          const stepEl = form.querySelector(`.form-step[data-step="${stepNum}"]`);
+          const fields = Array.from(stepEl.querySelectorAll('input, select, textarea')).filter(
+            (el) => el.type !== 'hidden'
+          );
+          let firstInvalidInStep = null;
+          for (const field of fields) {
+            const valid = markFieldInteractedAndValidate(field, false);
+            if (!valid && !firstInvalidInStep) {
+              firstInvalidInStep = field;
+            }
+          }
+          if (firstInvalidInStep) {
+            if (currentStep !== stepNum) {
+              goToStep(stepNum);
+            }
+            firstInvalidInStep.focus();
+            announceError(firstInvalidInStep);
+            return;
+          }
+        }
+
+        // Disable submit button after valid submission to prevent double-posts
+        if (submitBtn) {
+          submitBtn.disabled = true;
+          submitBtn.textContent = 'Creating Account...';
+        }
+
+        const formData = new FormData(form);
+        const memberName = String(formData.get('full_name') || 'Coffee Lover').trim();
+        const memberEmail = String(formData.get('email') || '').trim();
+
+        if (statusBanner) {
+          statusBanner.hidden = false;
+          statusBanner.textContent = `Welcome to The Daily Grind Rewards, ${memberName}! Your account (${memberEmail}) has been created and 50 bonus beans have been added to your balance.`;
+        }
+
+        if (submitBtn) {
+          submitBtn.textContent = 'Account Created';
+        }
+      });
+    })();
+  </script>
+
 </body>

 </html>

