+        faces.forEach((name) => {
+          if (name === 'front' && isHtmlInCanvasSupported) {
+            // Front face texture is populated from the live HTML form via texElementImage2D
+            uploadHtmlFormToTexture();
+          } else {
+            const c = createPackagingCanvas(name);
+            gl.bindTexture(gl.TEXTURE_2D, faceTextures[name]);
+            gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, c);
+          }
+        });
+      }
+
+      // Upload the live HTML <form> element into the front WebGL texture (HTML-in-Canvas API)
+      function uploadHtmlFormToTexture() {
+        if (!gl || !isHtmlInCanvasSupported || !faceTextures.front) return;
+        try {
+          gl.bindTexture(gl.TEXTURE_2D, faceTextures.front);
+          if (typeof gl.texElementImage2D === 'function') {
+            gl.texElementImage2D(
+              gl.TEXTURE_2D,
+              0,
+              gl.RGBA,
+              gl.RGBA,
+              gl.UNSIGNED_BYTE,
+              formElement
+            );
+          } else if (typeof gl.texElementSubImage2D === 'function') {
+            const w = Math.max(1, formElement.offsetWidth || 300);
+            const h = Math.max(1, formElement.offsetHeight || 370);
+            const internalFormat = gl.RGBA8 || gl.RGBA;
+            gl.texImage2D(gl.TEXTURE_2D, 0, internalFormat, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
+            gl.texElementSubImage2D(gl.TEXTURE_2D, 0, 0, 0, formElement);
+          }
+        } catch (err) {
+          // If called outside a paint callback in strict implementations, paint event will handle it
+        }
+      }
+
+      // Compute MVP matrices and synchronize the HTML form's 3D projection transform
+      function syncFormProjection(boxModelMatrix, viewProjectionMatrix) {
+        // Local transform mapping a [-0.5, 0.5] x [-0.5, 0.5] unit quad at z=0 to the front face (+Z) of the coffee box
+        const frontFaceLocalMatrix = mat4Multiply(
+          mat4Translate(0, 0, BOX_D / 2),
+          mat4Scale(BOX_W, BOX_H, 1)
+        );
+        const frontFaceModelMatrix = mat4Multiply(boxModelMatrix, frontFaceLocalMatrix);
+        const htmlElementMVP = mat4Multiply(viewProjectionMatrix, frontFaceModelMatrix);
+
+        // Check if the front face normal is facing the camera for pointer interactivity
+        const rotXRad = (rotXDeg * Math.PI) / 180;
+        const rotYRad = (rotYDeg * Math.PI) / 180;
+        const frontNormalZ = Math.cos(rotXRad) * Math.cos(rotYRad);
+        formElement.style.pointerEvents = frontNormalZ > 0.05 ? 'auto' : 'none';
+
+        if (isHtmlInCanvasSupported && typeof canvas.getElementTransform === 'function') {
+          // 1. Convert WebGL MVP Matrix to DOMMatrix
+          const mvpDOM = new DOMMatrix(Array.from(htmlElementMVP));
+
+          // 2. Normalize the HTML form (CSS pixels -> 1x1 unit square centered at origin with Y flipped)
+          const width = Math.max(1, formElement.offsetWidth || 300);
+          const height = Math.max(1, formElement.offsetHeight || 370);
+          const cssToUnitSpace = new DOMMatrix()
+            .scale(1 / width, -1 / height, 1)
+            .translate(-width / 2, -height / 2);
+
+          // 3. Map WebGL clip space [-1, 1] to the canvas viewport pixel space
+          const clipToCanvasViewport = new DOMMatrix()
+            .translate(canvas.width / 2, canvas.height / 2)
+            .scale(canvas.width / 2, -canvas.height / 2, 1);
+
+          // 4. Multiply: (Clip -> Pixels) * (MVP) * (Pixels -> Unit Square)
+          const screenSpaceTransform = clipToCanvasViewport
+            .multiply(mvpDOM)
+            .multiply(cssToUnitSpace);
+
+          // 5. Compute and apply the element transform via HTML-in-Canvas getElementTransform
+          const computedTransform = canvas.getElementTransform(formElement, screenSpaceTransform);
+          if (computedTransform) {
+            formElement.style.transform = computedTransform.toString();
+          }
+        } else {
+          // Synchronized 3D fallback projection for browsers without HTML-in-Canvas
+          const canvasRect = canvas.getBoundingClientRect();
+          const scaleFactor = canvasRect.height > 0 && gl ? canvasRect.height / canvas.height : 1;
+          const perspectivePx = FOCAL_LENGTH_PX * scaleFactor;
+          fallbackOverlay.style.perspective = perspectivePx + 'px';
+          const frontZPx = (BOX_D / 2) * 200; // 0.45 * 200 = 90px
+          fallbackPivot.style.transform =
+            `scale(${scaleFactor}) rotateX(${rotXDeg.toFixed(2)}deg) rotateY(${rotYDeg.toFixed(2)}deg)`;
+          formElement.style.transform = `translateZ(${frontZPx}px)`;
+          formElement.style.opacity = frontNormalZ > 0.05 ? '1' : '0';
+        }
+      }
+
+      // Render the 3D coffee box scene
+      function renderScene() {
+        const rotXRad = (rotXDeg * Math.PI) / 180;
+        const rotYRad = (rotYDeg * Math.PI) / 180;
+
+        // Model matrix: rotateX then rotateY (matching CSS rotateX(...) rotateY(...))
+        const boxModelMatrix = mat4Multiply(mat4RotateX(rotXRad), mat4RotateY(rotYRad));
+        const viewMatrix = mat4Translate(0, 0, -CAMERA_Z);
+        const fovyRad = 2 * Math.atan((canvas.height / 2) / FOCAL_LENGTH_PX);
+        const aspect = canvas.width / canvas.height;
+        const projMatrix = mat4Perspective(fovyRad, aspect, 0.1, 25.0);
+        const viewProjectionMatrix = mat4Multiply(projMatrix, viewMatrix);
+        const boxMVP = mat4Multiply(viewProjectionMatrix, boxModelMatrix);
+
+        if (gl && program) {
+          gl.viewport(0, 0, canvas.width, canvas.height);
+          gl.enable(gl.DEPTH_TEST);
+          gl.depthFunc(gl.LEQUAL);
+          gl.clearColor(0.16, 0.10, 0.09, 1.0);
+          gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
+
+          gl.useProgram(program);
+
+          gl.bindBuffer(gl.ARRAY_BUFFER, posBuffer);
+          gl.enableVertexAttribArray(attribs.aPosition);
+          gl.vertexAttribPointer(attribs.aPosition, 3, gl.FLOAT, false, 0, 0);
+
+          gl.bindBuffer(gl.ARRAY_BUFFER, uvBuffer);
+          gl.enableVertexAttribArray(attribs.aTexCoord);
+          gl.vertexAttribPointer(attribs.aTexCoord, 2, gl.FLOAT, false, 0, 0);
+
+          gl.bindBuffer(gl.ARRAY_BUFFER, normBuffer);
+          gl.enableVertexAttribArray(attribs.aNormal);
+          gl.vertexAttribPointer(attribs.aNormal, 3, gl.FLOAT, false, 0, 0);
+
+          gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
+
+          gl.uniformMatrix4fv(uniforms.uMVPMatrix, false, boxMVP);
+          gl.uniformMatrix4fv(uniforms.uModelMatrix, false, boxModelMatrix);
+          gl.uniform1i(uniforms.uSampler, 0);
+
+          const faceOrder = ['front', 'back', 'right', 'left', 'top', 'bottom'];
+          faceOrder.forEach((faceName, faceIdx) => {
+            gl.activeTexture(gl.TEXTURE0);
+            gl.bindTexture(gl.TEXTURE_2D, faceTextures[faceName]);
+            gl.drawElements(gl.TRIANGLES, 6, gl.UNSIGNED_SHORT, faceIdx * 6 * 2);
+          });
+        }
+
+        syncFormProjection(boxModelMatrix, viewProjectionMatrix);
+      }
+
+      // HTML-in-Canvas paint lifecycle event
+      function handleCanvasPaint() {
+        uploadHtmlFormToTexture();
+        renderScene();
+      }
+
+      canvas.onpaint = handleCanvasPaint;
+      canvas.addEventListener('paint', handleCanvasPaint);
+
+      function requestCanvasRepaint() {
+        if (typeof canvas.requestPaint === 'function') {
+          try {
+            canvas.requestPaint();
+          } catch (e) {
+            // Fallback to direct render
+          }
+        }
+        renderScene();
+      }
+
+      // Update UI sliders and rotation labels
+      function updateRotationUI() {
+        const roundedY = Math.round(rotYDeg);
+        const roundedX = Math.round(rotXDeg);
+        rotateYSlider.value = String(roundedY);
+        rotateXSlider.value = String(roundedX);
+        rotateYValue.textContent = roundedY + '°';
+        rotateXValue.textContent = roundedX + '°';
+      }
+
+      // Interactive pointer drag rotation (ignoring drags inside form inputs/buttons)
+      const viewportWrapper = document.getElementById('scene-viewport-wrapper');
+
+      function isInteractiveFormControl(target) {
+        if (!target || !target.closest) return false;
+        return Boolean(target.closest('input, select, textarea, button, label'));
+      }
+
+      viewportWrapper.addEventListener('pointerdown', (e) => {
+        if (isInteractiveFormControl(e.target)) {
+          return;
+        }
+        isDragging = true;
+        autoRotate = false;
+        toggleAutoRotateBtn.classList.remove('active');
+        toggleAutoRotateBtn.setAttribute('aria-pressed', 'false');
+        toggleAutoRotateBtn.textContent = 'Auto-Rotate: OFF';
+
+        dragStartX = e.clientX;
+        dragStartY = e.clientY;
+        dragStartRotY = targetRotYDeg;
+        dragStartRotX = targetRotXDeg;
+
+        if (viewportWrapper.setPointerCapture) {
+          try {
+            viewportWrapper.setPointerCapture(e.pointerId);
+          } catch (err) {}
+        }
+      });
+
+      viewportWrapper.addEventListener('pointermove', (e) => {
+        if (!isDragging) return;
+        const dx = e.clientX - dragStartX;
+        const dy = e.clientY - dragStartY;
+        targetRotYDeg = Math.max(-180, Math.min(180, dragStartRotY + dx * 0.45));
+        targetRotXDeg = Math.max(-65, Math.min(65, dragStartRotX - dy * 0.35));
+      });
+
+      function endDrag() {
+        isDragging = false;
+      }
+
+      viewportWrapper.addEventListener('pointerup', endDrag);
+      viewportWrapper.addEventListener('pointercancel', endDrag);
+
+      // Slider & preset button handlers
+      rotateYSlider.addEventListener('input', () => {
+        autoRotate = false;
+        toggleAutoRotateBtn.classList.remove('active');
+        toggleAutoRotateBtn.setAttribute('aria-pressed', 'false');
+        toggleAutoRotateBtn.textContent = 'Auto-Rotate: OFF';
+        targetRotYDeg = parseFloat(rotateYSlider.value) || 0;
+        rotYDeg = targetRotYDeg;
+        updateRotationUI();
+        requestCanvasRepaint();
+      });
+
+      rotateXSlider.addEventListener('input', () => {
+        autoRotate = false;
+        toggleAutoRotateBtn.classList.remove('active');
+        toggleAutoRotateBtn.setAttribute('aria-pressed', 'false');
+        toggleAutoRotateBtn.textContent = 'Auto-Rotate: OFF';
+        targetRotXDeg = parseFloat(rotateXSlider.value) || 0;
+        rotXDeg = targetRotXDeg;
+        updateRotationUI();
+        requestCanvasRepaint();
+      });
+
+      toggleAutoRotateBtn.addEventListener('click', () => {
+        autoRotate = !autoRotate;
+        animStartTime = performance.now();
+        toggleAutoRotateBtn.classList.toggle('active', autoRotate);
+        toggleAutoRotateBtn.setAttribute('aria-pressed', String(autoRotate));
+        toggleAutoRotateBtn.textContent = autoRotate ? 'Auto-Rotate: ON' : 'Auto-Rotate: OFF';
+      });
+
+      resetRotationBtn.addEventListener('click', () => {
+        autoRotate = false;
+        toggleAutoRotateBtn.classList.remove('active');
+        toggleAutoRotateBtn.setAttribute('aria-pressed', 'false');
+        toggleAutoRotateBtn.textContent = 'Auto-Rotate: OFF';
+        targetRotYDeg = -18;
+        targetRotXDeg = 10;
+      });
+
+      viewFrontBtn.addEventListener('click', () => {
+        autoRotate = false;
+        toggleAutoRotateBtn.classList.remove('active');
+        toggleAutoRotateBtn.setAttribute('aria-pressed', 'false');
+        toggleAutoRotateBtn.textContent = 'Auto-Rotate: OFF';
+        targetRotYDeg = 0;
+        targetRotXDeg = 0;
+      });
+
+      viewSideBtn.addEventListener('click', () => {
+        autoRotate = false;
+        toggleAutoRotateBtn.classList.remove('active');
+        toggleAutoRotateBtn.setAttribute('aria-pressed', 'false');
+        toggleAutoRotateBtn.textContent = 'Auto-Rotate: OFF';
+        targetRotYDeg = -34;
+        targetRotXDeg = 14;
+      });
+
+      // Sync form fields with live summary & 3D box packaging textures
+      function syncFormToBoxState(statusMessage) {
+        const recipient = (recipientInput.value || 'Coffee Lover').trim();
+        const roast = roastSelect.value;
+        const grind = grindSelect.value;
+        const bags = Math.max(1, Math.min(12, parseInt(bagsInput.value, 10) || 1));
+
+        summaryRecipient.textContent = recipient;
+        summaryRoast.textContent = roast;
+        summaryGrind.textContent = grind;
+        summaryBags.textContent = String(bags);
+
+        if (statusMessage) {
+          statusBox.textContent = statusMessage;
+        }
+
+        refreshPackagingTextures();
+        requestCanvasRepaint();
+      }
+
+      [recipientInput, roastSelect, grindSelect, bagsInput, emailInput, tastingNotesCheckbox].forEach((el) => {
+        el.addEventListener('input', () => {
+          syncFormToBoxState('Updated 3D box for ' + (recipientInput.value || 'your roast'));
+        });
+        el.addEventListener('change', () => {
+          syncFormToBoxState('Updated 3D box: ' + roastSelect.value + ' (' + grindSelect.value + ')');
+        });
+      });
+
+      surpriseBtn.addEventListener('click', () => {
+        const roasts = Array.from(roastSelect.options).map((o) => o.value);
+        const grinds = Array.from(grindSelect.options).map((o) => o.value);
+        const currentRoastIdx = roasts.indexOf(roastSelect.value);
+        roastSelect.value = roasts[(currentRoastIdx + 1) % roasts.length];
+        grindSelect.value = grinds[Math.floor(Math.random() * grinds.length)];
+        bagsInput.value = String(Math.floor(Math.random() * 4) + 1);
+        tastingNotesCheckbox.checked = true;
+        syncFormToBoxState('Surprise blend selected: ' + roastSelect.value + '!');
+      });
+
+      formElement.addEventListener('submit', (e) => {
+        e.preventDefault();
+        const recipient = (recipientInput.value || 'Coffee Lover').trim();
+        const roast = roastSelect.value;
+        const grind = grindSelect.value;
+        const bags = Math.max(1, Math.min(12, parseInt(bagsInput.value, 10) || 1));
+        syncFormToBoxState(
+          'Order confirmed! ' + bags + 'x ' + roast + ' (' + grind + ') for ' + recipient + '.'
+        );
+      });
+
+      // Initialize WebGL and start the 3D animation loop
+      initWebGL();
+      syncFormToBoxState();
+
+      function animate(now) {
+        if (autoRotate && !isDragging) {
+          const elapsed = (now - animStartTime) * 0.001;
+          targetRotYDeg = Math.sin(elapsed * 0.85) * 26;
+          targetRotXDeg = 8 + Math.cos(elapsed * 0.6) * 10;
+        }
+
+        // Smooth interpolation
+        rotYDeg += (targetRotYDeg - rotYDeg) * 0.14;
+        rotXDeg += (targetRotXDeg - rotXDeg) * 0.14;
+
+        updateRotationUI();
+        requestCanvasRepaint();
+        requestAnimationFrame(animate);
+      }
+
+      requestAnimationFrame(animate);
+    })();
+  </script>
