+            // Destroy previous active session if it isn't in clonedSessions
+            if (activeSession && activeSession !== selected.session) {
+              destroySessionSafely(activeSession);
+            }
+            activeSession = selected.session;
+            clonedSessions.splice(idx, 1);
+            renderBranchList();
+            updateContextUsageDisplay(activeSession);
+            branchOutputEl.textContent = `Switched active conversation to Branch #${selected.id} and destroyed previous session.`;
+          });
+        });
+
+        branchListEl.querySelectorAll('.destroy-branch-btn').forEach((btn) => {
+          btn.addEventListener('click', (e) => {
+            const idx = Number(e.currentTarget.getAttribute('data-index'));
+            const removed = clonedSessions.splice(idx, 1)[0];
+            if (removed) {
+              destroySessionSafely(removed.session);
+              renderBranchList();
+              branchOutputEl.textContent = `Destroyed Branch #${removed.id} and freed local AI resources.`;
+            }
+          });
+        });
+      }
+
+      // 1. Ask the Barista (Streaming Response with Availability Check)
+      askBaristaBtn.addEventListener('click', async () => {
+        const question = (questionInput.value || '').trim() || 'Tell me about the Maple Oat Latte and Cold Brew.';
+
+        if (currentAbortController) {
+          currentAbortController.abort();
+        }
+        currentAbortController = new AbortController();
+        const { signal } = currentAbortController;
+
+        baristaAnswerEl.textContent = 'Checking model availability...';
+        askBaristaBtn.disabled = true;
+        stopBtn.style.display = 'inline-block';
+
+        try {
+          const availabilityCheck = await checkModelAvailability();
+          if (!availabilityCheck.available) {
+            baristaAnswerEl.textContent = `Built-in AI model is not available (${availabilityCheck.status}). Unable to answer questions about the Maple Oat Latte or Cold Brew right now.`;
+            return;
+          }
+
+          const session = await ensureActiveSession(signal);
+          baristaAnswerEl.textContent = '';
+
+          const promptText = `Customer Question (Maple Oat Latte / Cold Brew): ${question}`;
+          const stream = session.promptStreaming(promptText, { signal });
+
+          let accumulated = '';
+          for await (const chunk of stream) {
+            // Handle both delta chunks (modern Chrome Prompt API) and cumulative chunks (older implementations)
+            if (typeof chunk === 'string') {
+              if (accumulated && chunk.startsWith(accumulated)) {
+                accumulated = chunk;
+              } else {
+                accumulated += chunk;
+              }
+              baristaAnswerEl.textContent = accumulated;
+            }
+          }
+
+          updateContextUsageDisplay(session);
+        } catch (err) {
+          if (err.name === 'AbortError') {
+            baristaAnswerEl.textContent += '\n[Generation stopped by user]';
+          } else {
+            baristaAnswerEl.textContent = `Error: ${err.message || String(err)}`;
+          }
+        } finally {
+          askBaristaBtn.disabled = false;
+          stopBtn.style.display = 'none';
+          currentAbortController = null;
+        }
+      });
+
+      stopBtn.addEventListener('click', () => {
+        if (currentAbortController) {
+          currentAbortController.abort();
+        }
+      });
+
+      // 2. Customer Feedback Analyzer (Structured JSON Response with score & category)
+      sentimentBtn.addEventListener('click', async () => {
+        const feedbackText = (feedbackInput.value || '').trim();
+        if (!feedbackText) {
+          sentimentOutputEl.textContent = JSON.stringify({ error: 'Please enter customer feedback to analyze.' }, null, 2);
+          return;
+        }
+
+        sentimentBtn.disabled = true;
+        sentimentOutputEl.textContent = 'Analyzing feedback with local AI...';
+
+        let analyzerSession = null;
+        try {
+          const check = await checkModelAvailability();
+          if (!check.available || !check.provider) {
+            throw new Error(`Built-in AI model is unavailable (${check.status}).`);
+          }
+
+          analyzerSession = await check.provider.create({
+            systemPrompt: 'You are a customer feedback sentiment analyzer for a coffee shop. Respond strictly with valid JSON containing numerical "score" and string "category".',
+            initialPrompts: [
+              {
+                role: 'system',
+                content: 'You are a customer feedback sentiment analyzer for a coffee shop. Respond strictly with valid JSON containing numerical "score" and string "category".'
+              }
+            ],
+            monitor: createDownloadMonitor
+          });
+
+          const rawResult = await analyzerSession.prompt(
+            `Analyze the following customer feedback and return a JSON object with "score" and "category":\n\n"${feedbackText}"`,
+            { responseConstraint: FEEDBACK_RESPONSE_SCHEMA }
+          );
+
+          let parsedResult;
+          if (typeof rawResult === 'object' && rawResult !== null) {
+            parsedResult = rawResult;
+          } else {
+            const cleaned = String(rawResult).replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
+            parsedResult = JSON.parse(cleaned);
+          }
+
+          const structuredOutput = {
+            score: typeof parsedResult.score === 'number' ? parsedResult.score : Number(parsedResult.score) || 5,
+            category: parsedResult.category || 'Positive'
+          };
+
+          sentimentOutputEl.textContent = JSON.stringify(structuredOutput, null, 2);
+        } catch (err) {
+          sentimentOutputEl.textContent = JSON.stringify(
+            {
+              error: err.message || 'Failed to analyze sentiment',
+              score: 0,
+              category: 'Unavailable'
+            },
+            null,
+            2
+          );
+        } finally {
+          // Clean up temporary analyzer session immediately after structured generation
+          destroySessionSafely(analyzerSession);
+          sentimentBtn.disabled = false;
+        }
+      });
+
+      // 3. Conversation Branching & Context Tracking (Clone Session & Cleanup)
+      let branchCounter = 1;
+      cloneBtn.addEventListener('click', async () => {
+        cloneBtn.disabled = true;
+        try {
+          const controller = new AbortController();
+          const sessionToClone = await ensureActiveSession(controller.signal);
+
+          // Prevent unbounded session growth by cleaning up stale branches when exceeding max keep limit
+          const MAX_ACTIVE_BRANCHES = 3;
+          while (clonedSessions.length >= MAX_ACTIVE_BRANCHES) {
+            const oldest = clonedSessions.shift();
+            destroySessionSafely(oldest.session);
+          }
+
+          if (typeof sessionToClone.clone !== 'function') {
+            throw new Error('Session cloning (session.clone) is not supported by this browser version.');
+          }
+
+          const clonedSession = await sessionToClone.clone({ signal: controller.signal });
+          attachSessionListeners(clonedSession);
+
+          const branchId = branchCounter++;
+          clonedSessions.push({
+            id: branchId,
+            session: clonedSession,
+            createdAt: new Date().toISOString()
+          });
+
+          updateContextUsageDisplay(sessionToClone);
+          renderBranchList();
+
+          const used = clonedSession.inputUsage ?? clonedSession.tokensSoFar ?? 0;
+          const quota = clonedSession.inputQuota ?? clonedSession.maxTokens ?? 0;
+          branchOutputEl.textContent = `Cloned active session into Branch #${branchId}. Context usage: ${used} / ${quota} tokens.`;
+        } catch (err) {
+          branchOutputEl.textContent = `Clone Error: ${err.message || String(err)}`;
+        } finally {
+          cloneBtn.disabled = false;
+        }
+      });
+
+      cleanupBtn.addEventListener('click', () => {
+        cleanupUnneededSessions();
+      });
+
+      // Ensure all sessions are destroyed when the page unloads to avoid memory leaks
+      window.addEventListener('pagehide', () => {
+        if (currentAbortController) {
+          currentAbortController.abort();
+        }
+        cleanupUnneededSessions();
+        destroySessionSafely(activeSession);
+        activeSession = null;
+      });
+    })();
+  </script>
