+      function openDrinkOverlay(drinkKey, triggerElement) {
+        if (!overlay) return;
+        const drink = DRINK_CATALOG[drinkKey] || DRINK_CATALOG['maple-oat-latte'];
+        lastFocusedTrigger = triggerElement || document.activeElement;
+
+        if (closeTimeoutId) {
+          clearTimeout(closeTimeoutId);
+          closeTimeoutId = null;
+        }
+
+        titleEl.textContent = drink.title;
+        badgeEl.textContent = drink.badge;
+        descEl.textContent = drink.description;
+        roastEl.textContent = drink.roast;
+        notesEl.textContent = drink.notes;
+        priceEl.textContent = drink.price;
+        imageEl.src = drink.image;
+        imageEl.alt = drink.title;
+        orderLinkEl.href = drink.href;
+
+        overlay.classList.remove('is-closing');
+        overlay.setAttribute('aria-hidden', 'false');
+
+        if (typeof overlay.showModal === 'function' && !overlay.open) {
+          try {
+            overlay.showModal();
+          } catch (_) {
+            overlay.setAttribute('open', '');
+          }
+        } else {
+          overlay.setAttribute('open', '');
+        }
+
+        overlay.classList.add('is-open');
+        document.body.dataset.lastAnimationState = 'overlay:opening:running';
+
+        if (closeBtn) {
+          closeBtn.focus();
+        }
+      }
+
+      function finalizeOverlayClose() {
+        if (!overlay) return;
+        overlay.classList.remove('is-open', 'is-closing');
+        overlay.setAttribute('aria-hidden', 'true');
+        if (typeof overlay.close === 'function' && overlay.open) {
+          try {
+            overlay.close();
+          } catch (_) {
+            overlay.removeAttribute('open');
+          }
+        } else {
+          overlay.removeAttribute('open');
+        }
+        document.body.dataset.lastAnimationState = 'overlay:closed:finished';
+        if (lastFocusedTrigger && typeof lastFocusedTrigger.focus === 'function') {
+          lastFocusedTrigger.focus();
+        }
+      }
+
+      function closeDrinkOverlay() {
+        if (!overlay || (!overlay.classList.contains('is-open') && !overlay.hasAttribute('open'))) {
+          return;
+        }
+
+        if (reducedMotionQuery.matches) {
+          finalizeOverlayClose();
+          return;
+        }
+
+        overlay.classList.remove('is-open');
+        overlay.classList.add('is-closing');
+        document.body.dataset.lastAnimationState = 'overlay:closing:running';
+
+        let settled = false;
+        function onCloseAnimationComplete(event) {
+          if (settled) return;
+          if (event && event.target !== overlay && event.target !== modal) return;
+          settled = true;
+          overlay.removeEventListener('animationend', onCloseAnimationComplete);
+          overlay.removeEventListener('transitionend', onCloseAnimationComplete);
