+            clearTimeout(closeTimeoutId);
+            closeTimeoutId = null;
+          }
+          finalizeOverlayClose();
+        }
+
+        overlay.addEventListener('animationend', onCloseAnimationComplete);
+        overlay.addEventListener('transitionend', onCloseAnimationComplete);
+        closeTimeoutId = setTimeout(onCloseAnimationComplete, 300);
+      }
+
+      document.querySelectorAll('.view-details-btn').forEach(function (button) {
+        button.addEventListener('click', function (event) {
+          event.preventDefault();
+          const drinkKey = button.getAttribute('data-drink');
+          openDrinkOverlay(drinkKey, button);
+        });
+      });
+
+      if (closeBtn) {
+        closeBtn.addEventListener('click', closeDrinkOverlay);
+      }
+
+      if (dismissBtn) {
+        dismissBtn.addEventListener('click', closeDrinkOverlay);
+      }
+
+      if (overlay) {
+        overlay.addEventListener('click', function (event) {
+          if (event.target === overlay) {
+            closeDrinkOverlay();
+          }
+        });
+
+        overlay.addEventListener('cancel', function (event) {
+          event.preventDefault();
+          closeDrinkOverlay();
+        });
+      }
+
+      document.addEventListener('keydown', function (event) {
+        if (event.key === 'Escape' && overlay && (overlay.open || overlay.classList.contains('is-open'))) {
+          event.preventDefault();
+          closeDrinkOverlay();
+        }
+      });
+    })();
