+      const nextBtn = document.getElementById('carousel-next');
+      const dots = Array.from(document.querySelectorAll('.carousel-dot'));
+
+      function getCardStepWidth() {
+        if (cards.length < 2) return cards[0] ? cards[0].offsetWidth : 300;
+        return cards[1].offsetLeft - cards[0].offsetLeft;
+      }
+
+      function getActiveIndex() {
+        const step = getCardStepWidth();
+        if (!step) return 0;
+        const idx = Math.round(carousel.scrollLeft / step);
+        return Math.max(0, Math.min(cards.length - 1, idx));
+      }
+
+      function scrollToCardIndex(index) {
+        const clamped = Math.max(0, Math.min(cards.length - 1, index));
+        const targetCard = cards[clamped];
+        if (!targetCard) return;
+        const leftOffset = targetCard.offsetLeft - carousel.offsetLeft;
+        carousel.scrollTo({ left: leftOffset, behavior: 'smooth' });
+      }
+
+      function updateCarouselControls() {
+        const activeIdx = getActiveIndex();
