+    const emailInput = document.getElementById('profile-email-input');
+
+    if (displayNameEl) displayNameEl.textContent = state.user.displayName;
+    if (emailEl) emailEl.textContent = state.user.name;
+    if (userIdEl) userIdEl.textContent = state.user.userId;
+    if (displayNameInput && document.activeElement !== displayNameInput) {
+      displayNameInput.value = state.user.displayName;
+    }
+    if (emailInput && document.activeElement !== emailInput) {
+      emailInput.value = state.user.name;
+    }
+  }
+
+  function renderPasskeys() {
+    const listEl = document.getElementById('passkey-list');
+    const emptyEl = document.getElementById('passkey-empty-state');
+    const countEl = document.getElementById('accepted-credentials-count');
+
+    if (countEl) {
+      countEl.textContent = String(state.passkeys.length);
+    }
+
+    if (!listEl) return;
+
+    if (state.passkeys.length === 0) {
+      listEl.innerHTML = '';
+      if (emptyEl) emptyEl.hidden = false;
+      return;
+    }
+
+    if (emptyEl) emptyEl.hidden = true;
+
+    listEl.innerHTML = state.passkeys
+      .map((pk) => {
+        const credId = pk.credentialId || pk.id;
+        const isEditing = state.editingCredentialId === credId;
+        const badgeText = pk.synced ? 'Synced Passkey' : 'Device-Bound';
+        const badgeClass = pk.synced ? 'passkey-badge--synced' : 'passkey-badge--device';
+
+        return `
+          <li class="passkey-item" data-credential-id="${escapeHtml(credId)}" data-testid="passkey-item">
+            <div class="passkey-item__main">
+              <div class="passkey-item__icon" aria-hidden="true">
+                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
+                  <circle cx="7.5" cy="15.5" r="5.5"></circle>
+                  <path d="m21 2-9.6 9.6"></path>
+                  <path d="m15.5 7.5 3 3L22 7l-3-3"></path>
+                </svg>
+              </div>
+              <div class="passkey-item__details">
+                ${
+                  isEditing
+                    ? `
+                  <form class="passkey-rename-form" data-action="submit-rename" data-credential-id="${escapeHtml(credId)}">
+                    <label class="sr-only" for="rename-input-${escapeHtml(credId)}">Rename passkey</label>
+                    <input
+                      id="rename-input-${escapeHtml(credId)}"
+                      type="text"
+                      name="passkeyName"
+                      class="passkey-rename-input"
+                      value="${escapeHtml(pk.name)}"
+                      aria-label="Passkey name"
+                      maxlength="80"
+                      required
+                    />
+                    <div class="passkey-rename-actions">
+                      <button type="submit" class="btn btn-sm btn-save-rename" data-action="save-rename" data-credential-id="${escapeHtml(credId)}">Save</button>
+                      <button type="button" class="btn btn-sm btn-outline btn-cancel-rename" data-action="cancel-rename" data-credential-id="${escapeHtml(credId)}">Cancel</button>
+                    </div>
+                  </form>
+                `
+                    : `
+                  <div class="passkey-item__header">
+                    <span class="passkey-name" data-testid="passkey-name">${escapeHtml(pk.name)}</span>
+                    <span class="passkey-badge ${badgeClass}">${escapeHtml(badgeText)}</span>
+                  </div>
+                `
+                }
+                <div class="passkey-meta">
+                  <span class="passkey-provider"><strong>Authenticator:</strong> ${escapeHtml(pk.provider || 'Platform Authenticator')}</span>
+                  <span class="passkey-meta-sep">&bull;</span>
+                  <span class="passkey-created"><strong>Created:</strong> ${escapeHtml(pk.createdAt)}</span>
+                  <span class="passkey-meta-sep">&bull;</span>
+                  <span class="passkey-last-used"><strong>Last used:</strong> ${escapeHtml(pk.lastUsedAt)}</span>
+                </div>
+                <div class="passkey-id-row">
+                  <span class="passkey-id-label">Credential ID:</span>
+                  <code class="passkey-credential-id" title="${escapeHtml(credId)}">${escapeHtml(credId)}</code>
+                </div>
+              </div>
+            </div>
+            <div class="passkey-item__actions">
+              ${
+                isEditing
+                  ? ''
+                  : `
+                <button
+                  type="button"
+                  class="btn btn-sm btn-outline btn-rename"
+                  data-action="rename"
+                  data-credential-id="${escapeHtml(credId)}"
+                  aria-label="Rename ${escapeHtml(pk.name)}"
+                >
+                  Rename
+                </button>
+              `
+              }
+              <button
+                type="button"
+                class="btn btn-sm btn-danger btn-delete"
+                data-action="delete"
+                data-credential-id="${escapeHtml(credId)}"
+                aria-label="Delete ${escapeHtml(pk.name)}"
+              >
+                Delete
+              </button>
+            </div>
+          </li>
+        `;
+      })
+      .join('');
+
+    if (state.editingCredentialId) {
+      const input = listEl.querySelector('.passkey-rename-input');
+      if (input) {
+        input.focus();
+        input.select();
+      }
+    }
+  }
+
+  function startRenamePasskey(credentialId) {
+    state.editingCredentialId = credentialId;
+    renderPasskeys();
+  }
+
+  function cancelRenamePasskey() {
+    state.editingCredentialId = null;
+    renderPasskeys();
+  }
+
+  async function renamePasskey(credentialId, newName) {
+    const trimmed = String(newName || '').trim();
+    if (!trimmed) {
+      showNotification('Please provide a non-empty name for your passkey.', 'error');
+      return false;
+    }
+
+    const target = state.passkeys.find((pk) => (pk.credentialId || pk.id) === credentialId);
+    if (!target) {
+      showNotification('Passkey not found.', 'error');
+      return false;
+    }
+
+    const oldName = target.name;
+    target.name = trimmed;
+    state.editingCredentialId = null;
+    savePasskeys(state.passkeys);
+    renderPasskeys();
+
+    showNotification(`Renamed passkey from "${oldName}" to "${trimmed}".`, 'success');
+    return true;
+  }
+
+  async function deletePasskey(credentialId) {
+    const index = state.passkeys.findIndex((pk) => (pk.credentialId || pk.id) === credentialId);
+    if (index === -1) {
+      showNotification('Passkey not found.', 'error');
+      return false;
+    }
+
+    const [removed] = state.passkeys.splice(index, 1);
+    if (state.editingCredentialId === credentialId) {
+      state.editingCredentialId = null;
+    }
+    savePasskeys(state.passkeys);
+    renderPasskeys();
+
+    const syncResult = await syncAuthenticatorCredentials('delete');
+    showNotification(
+      `Deleted passkey "${removed.name}" and synced browser authenticator (${syncResult.allAcceptedCredentialIds.length} active key${syncResult.allAcceptedCredentialIds.length === 1 ? '' : 's'} remaining).`,
+      'success'
+    );
+    return true;
+  }
+
+  async function registerNewPasskey(customName) {
+    const label = String(customName || '').trim() || `Passkey (${navigator.platform || 'Browser Authenticator'})`;
+    let newCredentialId = generateCredentialId();
+
+    if (
+      window.PublicKeyCredential &&
+      navigator.credentials &&
+      typeof navigator.credentials.create === 'function'
+    ) {
+      try {
+        const challenge = new Uint8Array(32);
+        window.crypto.getRandomValues(challenge);
+        const userIdBytes = base64UrlToUint8Array(state.user.userId);
+
+        const credential = await navigator.credentials.create({
+          publicKey: {
+            challenge,
+            rp: {
+              name: 'The Daily Grind Coffee Co.',
+              id: getRpId()
+            },
+            user: {
+              id: userIdBytes,
+              name: state.user.name,
+              displayName: state.user.displayName
+            },
+            pubKeyCredParams: [
+              { type: 'public-key', alg: -7 },
+              { type: 'public-key', alg: -257 }
+            ],
+            timeout: 15000,
+            authenticatorSelection: {
+              residentKey: 'required',
+              userVerification: 'preferred'
+            },
+            excludeCredentials: state.passkeys.map((pk) => ({
+              id: base64UrlToUint8Array(pk.credentialId || pk.id),
+              type: 'public-key'
+            }))
+          }
+        });
+
+        if (credential && credential.id) {
+          newCredentialId = credential.id;
+        }
+      } catch (err) {
+        // Fallback to generated Base64URL credential ID when no hardware/virtual authenticator completes ceremony
+        console.info('WebAuthn create ceremony skipped or cancelled; using generated passkey credential ID.', err);
+      }
+    }
+
+    const todayStr = new Date().toLocaleDateString('en-US', {
+      month: 'short',
+      day: 'numeric',
+      year: 'numeric'
+    });
+
+    const newPasskey = {
+      id: newCredentialId,
+      credentialId: newCredentialId,
+      name: label,
+      provider: 'Browser Passkey Provider',
+      createdAt: todayStr,
+      lastUsedAt: 'Just now',
+      transports: ['internal', 'hybrid'],
+      synced: true
+    };
+
+    state.passkeys.unshift(newPasskey);
+    savePasskeys(state.passkeys);
+    renderPasskeys();
+
+    const syncResult = await syncAuthenticatorCredentials('register');
+    showNotification(
+      `Registered new passkey "${label}" and synchronized ${syncResult.allAcceptedCredentialIds.length} accepted passkeys with your browser authenticator.`,
+      'success'
+    );
+    return newPasskey;
+  }
+
+  async function resetDemoPasskeys() {
+    state.passkeys = DEFAULT_PASSKEYS.map((pk) => ({ ...pk }));
+    state.user = { ...DEFAULT_USER };
+    state.editingCredentialId = null;
+    savePasskeys(state.passkeys);
+    saveUser(state.user);
+    renderUserProfile();
+    renderPasskeys();
+    await syncAuthenticatorCredentials('reset');
+    showNotification('Restored default registered passkeys and synchronized browser authenticator.', 'success');
+  }
+
+  function attachEventListeners() {
+    const listEl = document.getElementById('passkey-list');
+    if (listEl) {
+      listEl.addEventListener('click', (event) => {
+        const actionBtn = event.target.closest('[data-action]');
+        if (!actionBtn) return;
+
+        const action = actionBtn.getAttribute('data-action');
+        const credentialId = actionBtn.getAttribute('data-credential-id');
+
+        if (action === 'rename' && credentialId) {
+          startRenamePasskey(credentialId);
+        } else if (action === 'cancel-rename') {
+          cancelRenamePasskey();
+        } else if (action === 'delete' && credentialId) {
+          deletePasskey(credentialId);
+        }
+      });
+
+      listEl.addEventListener('submit', (event) => {
+        const form = event.target.closest('.passkey-rename-form');
+        if (!form) return;
+        event.preventDefault();
+        const credentialId = form.getAttribute('data-credential-id');
+        const input = form.querySelector('.passkey-rename-input');
+        if (credentialId && input) {
+          renamePasskey(credentialId, input.value);
+        }
+      });
+
+      listEl.addEventListener('keydown', (event) => {
+        if (event.key === 'Escape' && state.editingCredentialId) {
+          cancelRenamePasskey();
+        }
+      });
+    }
+
+    const addForm = document.getElementById('add-passkey-form');
+    if (addForm) {
+      addForm.addEventListener('submit', async (event) => {
+        event.preventDefault();
+        const nameInput = document.getElementById('new-passkey-name');
+        const customName = nameInput ? nameInput.value : '';
+        await registerNewPasskey(customName);
+        if (nameInput) nameInput.value = '';
+      });
+    }
+
+    const syncBtn = document.getElementById('sync-authenticator-btn');
+    if (syncBtn) {
+      syncBtn.addEventListener('click', async () => {
+        const res = await syncAuthenticatorCredentials('manual-sync');
+        showNotification(res.message, res.status === 'error' ? 'error' : 'success');
+      });
+    }
+
+    const resetBtn = document.getElementById('reset-passkeys-btn');
+    if (resetBtn) {
+      resetBtn.addEventListener('click', async () => {
+        await resetDemoPasskeys();
+      });
+    }
+
+    const profileForm = document.getElementById('account-profile-form');
+    if (profileForm) {
+      profileForm.addEventListener('submit', async (event) => {
+        event.preventDefault();
+        const displayNameInput = document.getElementById('profile-display-name-input');
+        const emailInput = document.getElementById('profile-email-input');
+        const nextDisplayName = displayNameInput ? displayNameInput.value.trim() : '';
+        const nextEmail = emailInput ? emailInput.value.trim() : '';
+
+        if (!nextDisplayName || !nextEmail) {
+          showNotification('Display name and email cannot be empty.', 'error');
+          return;
+        }
+
+        state.user.displayName = nextDisplayName;
+        state.user.name = nextEmail;
+        saveUser(state.user);
+        renderUserProfile();
+        await syncCurrentUserDetails();
+        showNotification(
+          `Updated account profile for ${nextDisplayName} and signaled updated user details to browser authenticator.`,
+          'success'
+        );
+      });
+    }
+  }
+
+  async function initPasskeyManagement() {
+    renderUserProfile();
+    renderPasskeys();
+    attachEventListeners();
+    await syncAuthenticatorCredentials('page-load');
+  }
+
+  window.DailyGrindPasskeys = {
+    state,
+    syncAuthenticatorCredentials,
+    syncCurrentUserDetails,
+    renamePasskey,
+    deletePasskey,
+    registerNewPasskey,
+    resetDemoPasskeys
+  };
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', initPasskeyManagement);
+  } else {
+    initPasskeyManagement();
+  }
+})();

