+      });
+    } catch (err: any) {
+      results.push({
+        method: 'PublicKeyCredential.signalAllAcceptedCredentials',
+        supported: true,
+        executed: false,
+        rpId,
+        timestamp,
+        payload: acceptedPayload,
+        error: err?.message || String(err),
+      });
+    }
+  } else {
+    results.push({
+      method: 'PublicKeyCredential.signalAllAcceptedCredentials',
+      supported: false,
+      executed: false,
+      rpId,
+      timestamp,
+      payload: acceptedPayload,
+    });
+  }
+
+  return results;
+}
