+        if (Array.isArray(allowedPasskeys) && allowedPasskeys.length > 0) {
+          publicKey.allowCredentials = allowedPasskeys.map(function (pk) {
+            const idStr = pk.rawIdBase64Url || pk.credentialId || pk.id;
+            const descriptor = {
+              id: base64UrlToUint8Array(idStr),
+              type: 'public-key'
+            };
+            return descriptor;
+          });
+        }
+
+        const assertion = await navigator.credentials.get({ publicKey: publicKey });
+        if (!assertion) {
+          throw new Error('Passkey authentication did not return an assertion.');
+        }
