+        const idsToMatch = [
+          assertionResult.credentialId,
+          assertionResult.rawIdBase64Url
+        ].filter(Boolean);
+
+        if (
+          idsToMatch.includes(pk.credentialId) ||
+          idsToMatch.includes(pk.id) ||
+          idsToMatch.includes(pk.rawIdBase64Url)
+        ) {
+          return true;
+        }
+
+        if (
+          assertionResult.userHandleText &&
+          pk.userHandle &&
+          assertionResult.userHandleText === pk.userHandle
+        ) {
+          return true;
+        }
+
+        if (
+          assertionResult.userHandleB64 &&
+          pk.userHandleBase64Url &&
+          assertionResult.userHandleB64 === pk.userHandleBase64Url
+        ) {
+          return true;
+        }
+
+        return false;
