+      function formatTimestamp(isoString) {
+        if (!isoString) return '—';
+        try {
+          const date = new Date(isoString);
+          if (isNaN(date.getTime())) return isoString;
+          return date.toLocaleString(undefined, {
+            month: 'short',
+            day: 'numeric',
+            year: 'numeric',
+            hour: '2-digit',
+            minute: '2-digit'
+          });
+        } catch (e) {
+          return isoString;
+        }
+      }
