+import React, { useState, useEffect, useRef } from 'react';
+import 'webauthn-polyfills';
+import aaguidsData from '../utils/aaguids.json';
+
+interface PasskeyItem {
+  id: string;
+  passkeyUserId: string;
+  credentialPublicKey: string;
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string;
+  providerIcon?: string;
+  name: string;
+  transports: string[];
+  lastUsedAt?: number;
+  registeredAt: number;
+  counter: number;
+}
+
+const aaguids = aaguidsData as Record<
+  string,
+  { name: string; icon_light?: string; icon_dark?: string }
+>;
+
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+function getAaguidInfo(cred: PasskeyItem) {
+  if (!cred.aaguid || cred.aaguid === ZERO_AAGUID) {
+    return {
+      providerName: cred.name || 'Unknown passkey provider',
+      providerIcon: cred.providerIcon,
+    };
+  }
+  const entry = aaguids[cred.aaguid];
+  return {
+    providerName: cred.name || entry?.name || 'Unknown passkey provider',
+    providerIcon: cred.providerIcon || entry?.icon_light || entry?.icon_dark,
+  };
+}
+
