+  const [editingCredName, setEditingCredName] = useState<string>('');
+
+  const [statusMessage, setStatusMessage] = useState<string | null>(null);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+  const [reauthVerified, setReauthVerified] = useState<boolean>(false);
+  const [reauthLoading, setReauthLoading] = useState<boolean>(false);
+  const [creatingPasskey, setCreatingPasskey] = useState<boolean>(false);
+
+  const reauthAbortControllerRef = useRef<AbortController>(new AbortController());
