@@ -0,0 +1,32 @@
+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { RP_ID } from '../../../utils/passkey-db';
+
+export const POST: APIRoute = async ({ session }) => {
+  try {
+    const userVerification = 'preferred';
+    const options = await generateAuthenticationOptions({
+      rpID: RP_ID,
+      allowCredentials: [], // Discoverable credentials flow
+      userVerification,
+    });
+
+    // Ensure rpId is explicitly included for client Signal API usage
+    options.rpId = RP_ID;
+    options.allowCredentials = [];
+
+    // Persist challenge and expected UV level in server session
+    await session?.set('authChallenge', options.challenge);
+    await session?.set('expectedUserVerification', userVerification);
+
+    return new Response(JSON.stringify(options), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate authentication options' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
