+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { db, RP_ID } from '../../../utils/passkey-db';
+
+export const POST: APIRoute = async ({ session }) => {
+  try {
+    const sessionUserId = await session?.get('userId');
+    const user = db.getActiveUser(sessionUserId);
+    const userPasskeys = db.findCredentialsByUserId(user.passkeyUserId);
+
+    const userVerification = 'preferred';
+    const options = await generateAuthenticationOptions({
+      rpID: RP_ID,
+      userVerification,
+      // Constrain allowCredentials strictly to the active signed-in user's credentials
+      allowCredentials: userPasskeys.map((cred) => ({
+        id: cred.id,
+        transports: cred.transports,
+      })),
+    });
+
+    options.rpId = RP_ID;
+    options.allowCredentials = userPasskeys.map((cred) => ({
+      type: 'public-key',
+      id: cred.id,
+      transports: cred.transports,
+    }));
+
+    await session?.set('reauthChallenge', options.challenge);
+    await session?.set('reauthUserId', user.id);
+    await session?.set('reauthExpectedUV', userVerification);
+
+    return new Response(JSON.stringify(options), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate reauthentication options' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
