@@ -0,0 +1,83 @@
+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { db, RP_ID } from '../../../utils/passkey-db';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  try {
+    const body = await request.json();
+    const credentialResponse = body.credential || body;
+    const expectedChallenge = await session?.get('reauthChallenge');
+    const reauthUserId = await session?.get('reauthUserId');
+    const expectedUV = (await session?.get('reauthExpectedUV')) || 'preferred';
+
+    if (!expectedChallenge) {
+      return new Response(
+        JSON.stringify({ error: 'Missing reauthentication challenge in session.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const activeUser = db.getActiveUser(reauthUserId);
+    const storedCredential = db.findCredentialById(credentialResponse.id);
+
+    if (!storedCredential) {
+      return new Response(
+        JSON.stringify({ error: 'Credential not found.', rpId: RP_ID }),
+        { status: 404, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    // Explicitly verify account ownership for step-up reauthentication
+    if (storedCredential.passkeyUserId !== activeUser.passkeyUserId) {
+      return new Response(
+        JSON.stringify({ error: 'Credential does not belong to the active signed-in user.' }),
+        { status: 403, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const origin = request.headers.get('origin') || url.origin;
+
+    const verification = await verifyAuthenticationResponse({
+      response: credentialResponse,
+      expectedChallenge,
+      expectedOrigin: origin,
+      expectedRPID: RP_ID,
+      credential: {
+        id: storedCredential.id,
+        publicKey: isoBase64URL.toBuffer(storedCredential.credentialPublicKey),
+        counter: storedCredential.counter,
+        transports: storedCredential.transports,
+      },
+      requireUserVerification: expectedUV === 'required',
+    });
+
+    if (!verification.verified) {
+      return new Response(
+        JSON.stringify({ error: 'Reauthentication verification failed.' }),
+        { status: 401, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    storedCredential.counter = verification.authenticationInfo.newCounter;
+    storedCredential.lastUsedAt = Date.now();
+    db.saveCredential(storedCredential);
+
+    await session?.set('reauthChallenge', undefined);
+    await session?.set('reauthenticatedAt', Date.now());
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        rpId: RP_ID,
+        reauthenticatedAt: Date.now(),
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Reauthentication verification error' }),
+      { status: 400, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
