+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { db, RP_ID, RP_NAME } from '../../../utils/passkey-db';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json().catch(() => ({}));
+    const isPromotionFlow = Boolean(body.promotion || body.conditional);
+    const isConditional = Boolean(body.conditional);
+
+    let sessionUserId = await session?.get('userId');
+    let user = db.getActiveUser(sessionUserId);
+
+    if (body.username) {
+      user = db.createOrGetUser(body.username, body.displayName || body.username);
+      await session?.set('userId', user.id);
+    }
+
+    const userExistingCredentials = db.findCredentialsByUserId(user.passkeyUserId);
+
+    const options = await generateRegistrationOptions({
+      rpName: RP_NAME,
+      rpID: RP_ID,
+      userName: user.name,
+      userDisplayName: user.displayName,
+      userID: isoBase64URL.toBuffer(user.passkeyUserId),
+      excludeCredentials: userExistingCredentials.map((cred) => ({
+        id: cred.id,
+        transports: cred.transports,
+      })),
+      authenticatorSelection: {
+        residentKey: 'required',
+        requireResidentKey: true,
+        userVerification: 'preferred',
+        ...(isPromotionFlow ? { authenticatorAttachment: 'platform' as const } : {}),
+      },
+    });
+
+    // Ensure rp.id and user.id are populated as required by WebAuthn JSON & Signal API
+    options.rp = { id: RP_ID, name: RP_NAME };
+    options.user = {
+      id: user.passkeyUserId,
+      name: user.name,
+      displayName: user.displayName,
+    };
+
+    await session?.set('regChallenge', options.challenge);
+    await session?.set('regUserId', user.id);
+    await session?.set('regUserVerification', 'preferred');
+    await session?.set('regConditional', isConditional);
+
+    return new Response(JSON.stringify(options), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate registration options' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
