new file mode 100644
index 0000000..cbef219
--- /dev/null
+++ b/src/pages/api/passkeys/register-verify.ts
@@ -0,0 +1,88 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { db, RP_ID, resolveAaguidMetadata, type StoredPasskeyCredential } from '../../../utils/passkey-db';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  try {
+    const body = await request.json();
+    const isConditional = Boolean(body.conditional || (await session?.get('regConditional')));
+    const expectedChallenge = await session?.get('regChallenge');
+    const regUserId = await session?.get('regUserId');
+    const expectedUserVerification = (await session?.get('regUserVerification')) || 'preferred';
+
+    if (!expectedChallenge) {
+      return new Response(
+        JSON.stringify({ error: 'Missing registration challenge in session.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const user = db.getActiveUser(regUserId);
+    const origin = request.headers.get('origin') || url.origin;
+
+    // When userVerification was 'preferred', relax requireUserVerification to false.
+    // When conditional creation is verified, relax requireUserPresence to false.
+    const verification = await verifyRegistrationResponse({
+      response: body.credential || body,
+      expectedChallenge,
+      expectedOrigin: origin,
+      expectedRPID: RP_ID,
+      requireUserPresence: !isConditional,
+      requireUserVerification: expectedUserVerification === 'required',
+    });
+
+    if (!verification.verified || !verification.registrationInfo) {
+      return new Response(
+        JSON.stringify({ error: 'Passkey registration verification failed.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const {
+      aaguid,
+      credential,
+      credentialType,
+      credentialDeviceType,
+      credentialBackedUp,
+    } = verification.registrationInfo;
+
+    const aaguidMeta = resolveAaguidMetadata(aaguid);
+    const rawResponse = body.credential || body;
+    const transports = rawResponse?.response?.transports || ['internal', 'hybrid'];
+
+    const newCred: StoredPasskeyCredential = {
+      id: credential.id,
+      passkeyUserId: user.passkeyUserId,
+      credentialPublicKey: isoBase64URL.fromBuffer(credential.publicKey),
+      credentialType,
+      credentialDeviceType,
+      credentialBackedUp,
+      aaguid,
+      providerIcon: aaguidMeta.providerIcon,
+      name: aaguidMeta.name,
+      transports,
+      registeredAt: Date.now(),
+      counter: credential.counter,
+    };
+
+    db.saveCredential(newCred);
+    await session?.set('userId', user.id);
+    await session?.set('regChallenge', undefined);
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        rpId: RP_ID,
+        userId: user.passkeyUserId,
+        credential: newCred,
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Registration verification error' }),
+      { status: 400, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
