+import type { APIRoute } from 'astro';
+import { db, RP_ID } from '../../../utils/passkey-db';
+
+export const GET: APIRoute = async ({ session }) => {
+  const sessionUserId = await session?.get('userId');
+  const user = db.getActiveUser(sessionUserId);
+  return new Response(
+    JSON.stringify({
+      id: user.id,
+      userId: user.passkeyUserId,
+      name: user.name,
+      displayName: user.displayName,
+      rpId: RP_ID,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const PUT: APIRoute = async ({ request, session }) => {
+  const sessionUserId = await session?.get('userId');
+  const user = db.getActiveUser(sessionUserId);
+  const body = await request.json();
+
+  const updatedUser = db.updateUser(user.id, {
+    name: body.name,
+    displayName: body.displayName,
+    password: body.password,
+  });
+
+  await session?.set('userId', updatedUser.id);
+
+  return new Response(
+    JSON.stringify({
+      id: updatedUser.id,
+      name: updatedUser.name,
+      displayName: updatedUser.displayName,
+      rpId: RP_ID,
+      userId: updatedUser.passkeyUserId,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
