@@ -0,0 +1,224 @@
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import type { AuthenticatorTransportFuture } from '@simplewebauthn/server';
+import aaguidsData from './aaguids.json';
+
+export const RP_ID = 'localhost';
+export const RP_NAME = 'The DevTools Times';
+
+export interface StoredPasskeyCredential {
+  id: string; // Base64URL-encoded credential ID (unique lookup key)
+  passkeyUserId: string; // Associated application user ID (Base64URL-encoded)
+  credentialPublicKey: string; // Base64URL-encoded public key used to verify assertion signatures
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice'; // Helps distinguish device-bound vs cloud-synced passkeys
+  credentialBackedUp: boolean; // Boolean backup state reported by the authenticator
+  aaguid: string; // Authenticator Attestation GUID
+  providerIcon?: string; // Provider icon derived from the AAGUID registry (dark or light theme URLs)
+  name: string; // Provider name derived from AAGUID registry or custom nickname
+  transports: AuthenticatorTransportFuture[]; // Array of transport names (e.g. 'internal', 'hybrid') necessary for exclusion options
+  lastUsedAt?: number; // Optional epoch timestamp of last sign-in
+  registeredAt: number; // Registration epoch timestamp
+  counter: number; // Authenticator sign-in signature counter used to prevent replay attacks
+}
+
+export interface StoredUser {
+  id: string; // Internal ID
+  passkeyUserId: string; // Valid unpadded Base64URL string
+  name: string; // Username
+  displayName: string; // Display name
+  password?: string;
+}
+
+const aaguids = aaguidsData as Record<
+  string,
+  { name: string; icon_light?: string; icon_dark?: string }
+>;
+
+export function resolveAaguidMetadata(aaguid: string): {
+  name: string;
+  providerIcon?: string;
+} {
+  if (!aaguid || aaguid === '00000000-0000-0000-0000-000000000000') {
+    return {
+      name: 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const provider = aaguids[aaguid];
+  return {
+    name: provider?.name || 'Unknown passkey provider',
+    providerIcon: provider?.icon_light || provider?.icon_dark,
+  };
+}
+
+// Seed default demo user and valid Base64URL credentials so Account Settings works out-of-the-box
+const DEFAULT_USER_PASSKEY_ID = Buffer.from('devtools-editor-user-01').toString('base64url');
+const SEED_CRED_1_ID = Buffer.from('devtools-passkey-cred-gpm-01').toString('base64url');
+const SEED_CRED_2_ID = Buffer.from('devtools-passkey-cred-icloud-02').toString('base64url');
+
+const gpmMeta = resolveAaguidMetadata('ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4');
+const icloudMeta = resolveAaguidMetadata('fbfc3007-154e-4ecc-8c0b-6e020557d7bd');
+
+interface PasskeyStoreState {
+  users: Map<string, StoredUser>;
+  credentials: Map<string, StoredPasskeyCredential>;
+  defaultUserId: string;
+}
+
+// Persist across module reloads in dev/SSR
+const globalStore = globalThis as unknown as { __passkeyStore?: PasskeyStoreState };
+
+function initStore(): PasskeyStoreState {
+  if (globalStore.__passkeyStore) {
+    return globalStore.__passkeyStore;
+  }
+
+  const users = new Map<string, StoredUser>();
+  const credentials = new Map<string, StoredPasskeyCredential>();
+
+  const defaultUser: StoredUser = {
+    id: DEFAULT_USER_PASSKEY_ID,
+    passkeyUserId: DEFAULT_USER_PASSKEY_ID,
+    name: 'alex.editor@devtoolstimes.dev',
+    displayName: 'Alex Rivera',
+    password: 'password123',
+  };
+  users.set(defaultUser.id, defaultUser);
+
+  const now = Date.now();
+  const seedCred1: StoredPasskeyCredential = {
+    id: SEED_CRED_1_ID,
+    passkeyUserId: defaultUser.passkeyUserId,
+    credentialPublicKey: Buffer.from('seed-public-key-gpm-01').toString('base64url'),
+    credentialType: 'public-key',
+    credentialDeviceType: 'multiDevice',
+    credentialBackedUp: true,
+    aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+    providerIcon: gpmMeta.providerIcon,
+    name: gpmMeta.name,
+    transports: ['internal', 'hybrid'],
+    registeredAt: now - 1000 * 60 * 60 * 24 * 14, // 14 days ago
+    lastUsedAt: now - 1000 * 60 * 60 * 3, // 3 hours ago
+    counter: 4,
+  };
+
+  const seedCred2: StoredPasskeyCredential = {
+    id: SEED_CRED_2_ID,
+    passkeyUserId: defaultUser.passkeyUserId,
+    credentialPublicKey: Buffer.from('seed-public-key-icloud-02').toString('base64url'),
+    credentialType: 'public-key',
+    credentialDeviceType: 'multiDevice',
+    credentialBackedUp: true,
+    aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+    providerIcon: icloudMeta.providerIcon,
+    name: icloudMeta.name,
+    transports: ['internal', 'hybrid'],
+    registeredAt: now - 1000 * 60 * 60 * 24 * 30, // 30 days ago
+    lastUsedAt: now - 1000 * 60 * 60 * 24 * 2, // 2 days ago
+    counter: 12,
+  };
+
+  credentials.set(seedCred1.id, seedCred1);
+  credentials.set(seedCred2.id, seedCred2);
+
+  const state: PasskeyStoreState = {
+    users,
+    credentials,
+    defaultUserId: defaultUser.id,
+  };
+
+  globalStore.__passkeyStore = state;
+  return state;
+}
+
+export const db = {
+  getActiveUser(sessionUserId?: string): StoredUser {
+    const store = initStore();
+    if (sessionUserId && store.users.has(sessionUserId)) {
+      return store.users.get(sessionUserId)!;
+    }
+    return store.users.get(store.defaultUserId)!;
+  },
+
+  findUserById(userId: string): StoredUser | undefined {
+    const store = initStore();
+    return store.users.get(userId);
+  },
+
+  findUserByName(username: string): StoredUser | undefined {
+    const store = initStore();
+    for (const user of store.users.values()) {
+      if (user.name.toLowerCase() === username.toLowerCase()) {
+        return user;
+      }
+    }
+    return undefined;
+  },
+
+  createOrGetUser(username: string, displayName?: string, password?: string): StoredUser {
+    const store = initStore();
+    const existing = this.findUserByName(username);
+    if (existing) {
+      if (displayName) existing.displayName = displayName;
+      if (password) existing.password = password;
+      return existing;
+    }
+    const rawId = `user-${username}-${Date.now()}`;
+    const passkeyUserId = isoBase64URL.fromUTF8String(rawId);
+    const newUser: StoredUser = {
+      id: passkeyUserId,
+      passkeyUserId,
+      name: username,
+      displayName: displayName || username,
+      password,
+    };
+    store.users.set(newUser.id, newUser);
+    return newUser;
+  },
+
+  updateUser(
+    userId: string,
+    updates: { name?: string; displayName?: string; password?: string }
+  ): StoredUser {
+    const store = initStore();
+    const user = this.getActiveUser(userId);
+    if (typeof updates.name === 'string' && updates.name.trim()) {
+      user.name = updates.name.trim();
+    }
+    if (typeof updates.displayName === 'string' && updates.displayName.trim()) {
+      user.displayName = updates.displayName.trim();
+    }
+    if (typeof updates.password === 'string' && updates.password) {
+      user.password = updates.password;
+    }
+    store.users.set(user.id, user);
+    return user;
+  },
+
+  findCredentialsByUserId(passkeyUserId: string): StoredPasskeyCredential[] {
+    const store = initStore();
+    const list: StoredPasskeyCredential[] = [];
+    for (const cred of store.credentials.values()) {
+      if (cred.passkeyUserId === passkeyUserId) {
+        list.push(cred);
+      }
+    }
+    return list.sort((a, b) => b.registeredAt - a.registeredAt);
+  },
+
+  findCredentialById(credentialId: string): StoredPasskeyCredential | undefined {
+    const store = initStore();
+    return store.credentials.get(credentialId);
+  },
+
+  saveCredential(cred: StoredPasskeyCredential): StoredPasskeyCredential {
+    const store = initStore();
+    store.credentials.set(cred.id, cred);
+    return cred;
+  },
+
+  deleteCredential(credentialId: string): boolean {
+    const store = initStore();
+    return store.credentials.delete(credentialId);
+  },
+};

