+import React, { useState, useEffect } from 'react';
+import {
+  FingerPrintIcon,
+  ShieldCheckIcon,
+  KeyIcon,
+  PlusCircleIcon,
+  TrashIcon,
+  PencilSquareIcon,
+  CheckCircleIcon,
+  ExclamationCircleIcon,
+  ClockIcon,
+  DevicePhoneMobileIcon,
+  CpuChipIcon,
+  LockClosedIcon,
+  ArrowPathIcon,
+  UserCircleIcon,
+  ClipboardDocumentCheckIcon,
+  ExclamationTriangleIcon,
+} from '@heroicons/react/24/outline';
+import {
+  type PasskeyCredentialRecord,
+  type AuthSession,
+  type WebAuthnCapabilities,
+  type WebAuthnCeremonyEvent,
+  type AuthenticatorAttachmentPreference,
+  type UserVerificationPreference,
+  type ResidentKeyPreference,
+  type AttestationConveyancePreference,
+  detectWebAuthnCapabilities,
+  getStoredPasskeys,
+  getStoredSession,
+  setStoredSession,
+  isReauthFresh,
+  registerPasskey,
+  authenticateWithPasskey,
+  renamePasskeyCredential,
+  deletePasskeyCredential,
+  getCeremonyLogs,
+} from '../utils/passkeys';
+import ReauthModal from './ReauthModal';
+
+interface PendingSensitiveAction {
+  title: string;
+  description: string;
+  execute: (verifiedRecord: PasskeyCredentialRecord) => void;
+}
+
+export default function AccountSettings() {
+  const [session, setSession] = useState<AuthSession | null>(null);
+  const [passkeys, setPasskeys] = useState<PasskeyCredentialRecord[]>([]);
+  const [capabilities, setCapabilities] = useState<WebAuthnCapabilities | null>(null);
+  const [ceremonyLogs, setCeremonyLogs] = useState<WebAuthnCeremonyEvent[]>([]);
+  const [filterCurrentUserOnly, setFilterCurrentUserOnly] = useState(false);
+
+  // Account profile state
+  const [accountUsername, setAccountUsername] = useState('editor@devtoolstimes.dev');
+  const [accountDisplayName, setAccountDisplayName] = useState('Casey Vance (Senior Editor)');
+  const [accountEmail, setAccountEmail] = useState('editor@devtoolstimes.dev');
+  const [passwordlessOnlyMode, setPasswordlessOnlyMode] = useState(false);
+
+  // Add new passkey form state
+  const [showAddForm, setShowAddForm] = useState(false);
+  const [newPasskeyNickname, setNewPasskeyNickname] = useState('');
+  const [authenticatorAttachment, setAuthenticatorAttachment] =
+    useState<AuthenticatorAttachmentPreference>('any');
+  const [userVerification, setUserVerification] =
+    useState<UserVerificationPreference>('preferred');
+  const [residentKey, setResidentKey] = useState<ResidentKeyPreference>('required');
+  const [attestation, setAttestation] = useState<AttestationConveyancePreference>('none');
+  const [addingPasskey, setAddingPasskey] = useState(false);
+
+  // Rename state
+  const [editingPasskeyId, setEditingPasskeyId] = useState<string | null>(null);
+  const [editingNickname, setEditingNickname] = useState('');
+
+  // Reauthentication state
+  const [requireReauthForSensitive, setRequireReauthForSensitive] = useState(true);
+  const [pendingAction, setPendingAction] = useState<PendingSensitiveAction | null>(null);
+  const [reauthenticatingNow, setReauthenticatingNow] = useState(false);
+
+  //Sensitive action demo states (Email change, API key reveal, Delete account)
+  const [newEmailInput, setNewEmailInput] = useState('');
+  const [showEmailEditor, setShowEmailEditor] = useState(false);
+  const [revealedApiKey, setRevealedApiKey] = useState<string | null>(null);
+
+  // Feedback banners
+  const [statusMessage, setStatusMessage] = useState<string | null>(null);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+
+  const baseUrl = import.meta.env.BASE_URL || '/devtools-times/';
+
+  const refreshState = () => {
+    const currentSession = getStoredSession();
+    setSession(currentSession);
+    if (currentSession) {
+      setAccountUsername(currentSession.username);
+      setAccountDisplayName(currentSession.displayName || currentSession.username);
+      setAccountEmail(currentSession.email || `${currentSession.username}@devtoolstimes.dev`);
+    }
+    setPasskeys(getStoredPasskeys());
+    setCeremonyLogs(getCeremonyLogs());
+  };
+
+  useEffect(() => {
+    refreshState();
+    detectWebAuthnCapabilities().then(setCapabilities);
+
+    const onPasskeysUpdated = () => setPasskeys(getStoredPasskeys());
+    const onSessionUpdated = () => refreshState();
+    const onCeremonyLog = () => setCeremonyLogs(getCeremonyLogs());
+
+    window.addEventListener('passkeys-updated', onPasskeysUpdated);
+    window.addEventListener('auth-session-updated', onSessionUpdated);
+    window.addEventListener('webauthn-ceremony-log', onCeremonyLog);
