@@ -0,0 +1,148 @@
+import React, { useState } from 'react';
+import {
+  FingerPrintIcon,
+  ShieldCheckIcon,
+  ExclamationCircleIcon,
+  XMarkIcon,
+  LockClosedIcon,
+} from '@heroicons/react/24/outline';
+import {
+  type PasskeyCredentialRecord,
+  authenticateWithPasskey,
+} from '../utils/passkeys';
+
+export interface ReauthModalProps {
+  isOpen: boolean;
+  username?: string;
+  actionTitle: string;
+  actionDescription: string;
+  onSuccess: (record: PasskeyCredentialRecord) => void;
+  onCancel: () => void;
+}
+
+export default function ReauthModal({
+  isOpen,
+  username,
+  actionTitle,
+  actionDescription,
+  onSuccess,
+  onCancel,
+}: ReauthModalProps) {
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  if (!isOpen) return null;
+
+  const handleVerifyPasskey = async () => {
+    setError(null);
+    setLoading(true);
+    try {
+      const result = await authenticateWithPasskey({
+        username,
+        userVerification: 'required',
+        isReauthentication: true,
+        allowAnyDiscoverable: false,
+      });
+      onSuccess(result.record);
+    } catch (err: any) {
+      setError(err?.message || 'Passkey verification failed or was cancelled.');
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  return (
+    <div
+      className="fixed inset-0 z-[99999] bg-black/50 backdrop-blur-xs flex items-center justify-center p-4"
+      role="dialog"
+      aria-modal="true"
+      aria-labelledby="reauth-modal-title"
+      data-testid="reauth-modal"
+      onClick={onCancel}
+    >
+      <div
+        className="bg-white rounded-xl shadow-2xl border border-gray-200 max-w-md w-full overflow-hidden"
+        onClick={(e) => e.stopPropagation()}
+      >
+        {/* Modal Header */}
+        <div className="bg-gray-900 text-white px-5 py-4 flex items-center justify-between">
+          <div className="flex items-center gap-2.5">
+            <div className="w-9 h-9 rounded-full bg-amber-400/20 border border-amber-400/40 flex items-center justify-center">
+              <ShieldCheckIcon className="w-5 h-5 text-amber-400" />
+            </div>
+            <div>
+              <h3 id="reauth-modal-title" className="text-base font-bold">
+                Reauthentication Required
+              </h3>
+              <p className="text-xs text-gray-300">Step-up WebAuthn security verification</p>
+            </div>
+          </div>
+          <button
+            type="button"
+            onClick={onCancel}
+            aria-label="Close reauthentication dialog"
+            className="text-gray-400 hover:text-white p-1 rounded-md"
+          >
+            <XMarkIcon className="w-5 h-5" />
+          </button>
+        </div>
+
+        {/* Body */}
+        <div className="p-5 space-y-4">
+          <div className="p-3.5 bg-amber-50 border border-amber-200 rounded-lg">
+            <div className="flex items-start gap-2.5">
+              <LockClosedIcon className="w-5 h-5 text-amber-700 shrink-0 mt-0.5" />
+              <div className="text-xs text-gray-800 space-y-1">
+                <p className="font-bold text-gray-900">{actionTitle}</p>
+                <p>{actionDescription}</p>
+                {username && (
+                  <p className="text-gray-600 pt-1">
+                    Verifying identity for: <span className="font-semibold text-gray-900">{username}</span>
+                  </p>
+                )}
+              </div>
+            </div>
+          </div>
+
+          {error && (
+            <div
+              className="p-3 text-xs text-red-800 bg-red-50 border border-red-200 rounded-lg flex items-start gap-2"
+              role="alert"
+              data-testid="reauth-error"
+            >
+              <ExclamationCircleIcon className="w-4 h-4 text-red-600 shrink-0 mt-0.5" />
+              <span>{error}</span>
+            </div>
+          )}
+
+          <p className="text-xs text-gray-600 leading-relaxed">
+            To protect your account, please verify your identity using a registered passkey with{' '}
+            <code className="bg-gray-100 px-1 py-0.5 rounded text-gray-800">userVerification: "required"</code>.
+          </p>
+
+          <div className="flex items-center justify-end gap-2.5 pt-2">
+            <button
+              type="button"
+              onClick={onCancel}
+              disabled={loading}
+              data-testid="reauth-cancel-btn"
+              className="px-4 py-2 rounded-lg border border-gray-300 text-xs font-semibold text-gray-700 hover:bg-gray-50"
+            >
+              Cancel
+            </button>
+            <button
+              type="button"
+              onClick={handleVerifyPasskey}
+              disabled={loading}
+              data-testid="reauth-verify-btn"
+              className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-amber-400 hover:bg-amber-500 text-gray-950 text-xs font-semibold shadow-xs disabled:opacity-60"
+            >
+              <FingerPrintIcon className="w-4 h-4" />
+              <span>{loading ? 'Verifying with Authenticator...' : 'Verify with Passkey'}</span>
+            </button>
+          </div>
+        </div>
+      </div>
+    </div>
+  );
+}
