+          'Browser-mediated FedCM is not active in this environment; continuing in privacy-preserving Guest Mode.';
+        return;
+      }
+
+      try {
+        const nonceBytes = new Uint8Array(16);
+        crypto.getRandomValues(nonceBytes);
+        const nonce = btoa(String.fromCharCode(...nonceBytes));
+
+        const credential = await navigator.credentials.get({
+          identity: {
+            providers: [
+              {
+                configURL: 'https://idp.dailygrind.example/fedcm.json',
+                clientId: 'daily-grind-web-rp',
+                nonce,
+              },
+            ],
+          },
+        });
+
+        if (credential && credential.token) {
+          safeLog('FedCM', `Authenticated with token=${credential.token}`);
+          statusEl.textContent = 'Signed in via browser-mediated FedCM without third-party tracking cookies.';
+        }
+      } catch {
