+          ephemeralSessionOrder: localOrder,
+          serverDataSnapshot: apiResult.ok ? apiResult.body : 'Static mode (zero server PII stored)',
+          webStoragePIIKeys: 0,
+        };
+        outputEl.textContent = JSON.stringify(summary, null, 2);
+      });
+    }
+
+    if (correctDataBtn && outputEl) {
+      correctDataBtn.addEventListener('click', () => {
+        const aliasInput = document.getElementById('pickup-alias');
+        const bracketSelect = document.getElementById('age-bracket');
+        const currentOrder = ephemeralState.get('currentOrder') || {};
