+  // Connection-Allowlist scoped to document/worker destinations
+  const secFetchDest = req.headers['sec-fetch-dest'] || 'document';
+  if (ALLOWLIST_DESTS.has(String(secFetchDest).toLowerCase())) {
+    res.setHeader(
+      'Connection-Allowlist',
+      buildConnectionAllowlistHeader({
+        allowSelf: true,
+        patterns: [
+          'https://images.unsplash.com/*',
+          'https://img.youtube.com/*',
+          'https://www.youtube-nocookie.com/*',
+          'https://x.com/intent/tweet*',
+        ],
+        reportTo: 'main-endpoint',
+        redirects: 'block',
+        webrtc: 'block',
+      }),
+    );
+  }
