+  // Enforced Content Security Policy (with Trusted Types, per-request nonce, and static SHA-384 hash)
+  const PRIVACY_JS_HASH = "'sha384-E8deN7onW9KWSfpLfFFeBTZzC8ICpvUGQpFCbdbDNkiT4TRa2LBLk/dRO0J7lW2f'";
+  const scriptSrc = nonce
+    ? `script-src 'self' 'nonce-${nonce}' ${PRIVACY_JS_HASH} 'strict-dynamic' 'report-sample'`
+    : `script-src 'self' ${PRIVACY_JS_HASH} 'report-sample'`;
