+const http = require('http');
+const fs = require('fs');
+const path = require('path');
+const { URL } = require('url');
+
+const CSP_HEADER = [
+  "default-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "style-src 'self' 'unsafe-inline'",
+  "script-src 'self' 'unsafe-inline'",
+  "connect-src 'self'",
+  "form-action 'self'",
+  "base-uri 'self'",
+  "object-src 'none'"
+].join('; ');
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon'
+};
+
+const subscribers = [];
+
+function getPort() {
+  const args = process.argv.slice(2);
+  for (let i = 0; i < args.length; i++) {
+    if ((args[i] === '--port' || args[i] === '-p') && args[i + 1]) {
+      const parsed = Number(args[i + 1]);
+      if (!Number.isNaN(parsed) && parsed > 0) {
+        return parsed;
+      }
+    }
+    if (args[i].startsWith('--port=')) {
+      const parsed = Number(args[i].split('=')[1]);
+      if (!Number.isNaN(parsed) && parsed > 0) {
+        return parsed;
+      }
+    }
+  }
+  return Number(process.env.PORT) || 11222;
+}
+
+function setSecurityHeaders(res) {
+  res.setHeader('Content-Security-Policy', CSP_HEADER);
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+}
+
+function parseBody(req) {
+  return new Promise((resolve, reject) => {
+    let raw = '';
+    req.on('data', (chunk) => {
+      raw += chunk.toString('utf8');
+      if (raw.length > 1e6) {
+        reject(new Error('Payload too large'));
+        req.destroy();
+      }
+    });
+    req.on('end', () => {
+      const contentType = (req.headers['content-type'] || '').toLowerCase();
+      if (!raw.trim()) {
+        return resolve({});
+      }
+      if (contentType.includes('application/json')) {
+        try {
+          return resolve(JSON.parse(raw));
+        } catch (err) {
+          return reject(new Error('Invalid JSON'));
+        }
+      }
+      if (contentType.includes('application/x-www-form-urlencoded')) {
+        const params = new URLSearchParams(raw);
+        return resolve(Object.fromEntries(params.entries()));
+      }
+      try {
+        return resolve(JSON.parse(raw));
+      } catch {
+        const params = new URLSearchParams(raw);
+        if (params.has('email')) {
+          return resolve(Object.fromEntries(params.entries()));
+        }
+        return resolve({ email: raw.trim() });
+      }
+    });
+    req.on('error', reject);
+  });
+}
+
+function isValidEmail(email) {
+  return typeof email === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
+}
+
+const NEWSLETTER_PATHS = new Set([
+  '/subscribe',
+  '/api/subscribe',
+  '/newsletter',
+  '/api/newsletter',
+  '/signup',
+  '/api/signup'
+]);
+
+const server = http.createServer(async (req, res) => {
+  setSecurityHeaders(res);
+
+  const reqUrl = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  const pathname = reqUrl.pathname;
+
+  if (req.method === 'OPTIONS') {
+    res.writeHead(204);
+    res.end();
+    return;
+  }
+
+  if (pathname === '/favicon.ico') {
+    res.writeHead(204);
+    res.end();
+    return;
+  }
+
+  if (req.method === 'GET' && (pathname === '/subscribers' || pathname === '/api/subscribers')) {
+    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(JSON.stringify({ ok: true, subscribers }));
+    return;
+  }
+
+  if (
+    (req.method === 'POST' && (NEWSLETTER_PATHS.has(pathname) || pathname === '/')) ||
+    (req.method === 'GET' && NEWSLETTER_PATHS.has(pathname) && reqUrl.searchParams.has('email'))
+  ) {
+    try {
+      const body = req.method === 'POST' ? await parseBody(req) : Object.fromEntries(reqUrl.searchParams.entries());
+      const email = typeof body.email === 'string' ? body.email.trim() : '';
+
+      if (!isValidEmail(email)) {
+        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(
+          JSON.stringify({
+            ok: false,
+            error: "Sorry, your request can't go through. Please provide a valid email address."
+          })
