+++ b/src/pages/api/verify-phone.ts
@@ -0,0 +1,145 @@
+import type { APIRoute } from 'astro';
+
+// In-memory store for verification codes keyed by normalized phone number
+const otpStore = new Map<string, { code: string; expiresAt: number }>();
+
+function normalizePhone(phone: string): string {
+  const trimmed = phone.trim();
+  const hasPlus = trimmed.startsWith('+');
+  const digits = trimmed.replace(/\D/g, '');
+  return hasPlus ? `+${digits}` : digits;
+}
+
+function isValidPhone(phone: string): boolean {
+  const digits = phone.replace(/\D/g, '');
+  return digits.length >= 7 && digits.length <= 15;
+}
+
+export const POST: APIRoute = async ({ request, url }) => {
+  try {
+    const body = await request.json();
+    const { action, phone, code } = body;
+
+    if (!phone || typeof phone !== 'string' || !isValidPhone(phone)) {
+      return new Response(
+        JSON.stringify({
+          error: 'INVALID_PHONE',
+          message: 'Please provide a valid phone number (7 to 15 digits).',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const normalized = normalizePhone(phone);
+
+    if (action === 'send') {
+      const generatedCode = String(Math.floor(100000 + Math.random() * 900000));
+      const expiresAt = Date.now() + 5 * 60 * 1000; // 5 minutes
+      otpStore.set(normalized, { code: generatedCode, expiresAt });
+
+      const host = url.hostname || 'localhost';
+      // Origin-bound one-time code SMS format for WebOTP API
+      const smsMessage = `Your DevTools Times verification code is ${generatedCode}.\n\n@${host} #${generatedCode}`;
+
+      return new Response(
+        JSON.stringify({
+          success: true,
+          phone: normalized,
+          message: 'Verification code sent via SMS.',
+          smsTemplate: smsMessage,
+        }),
+        {
+          status: 200,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (action === 'verify') {
+      if (!code || typeof code !== 'string' || !/^\d{6}$/.test(code.trim())) {
+        return new Response(
+          JSON.stringify({
+            error: 'INVALID_OTP_FORMAT',
+            message: 'Please enter a valid 6-digit one-time passcode.',
+          }),
+          {
+            status: 400,
+            headers: { 'Content-Type': 'application/json' },
+          }
+        );
+      }
+
+      const cleanCode = code.trim();
+      const record = otpStore.get(normalized);
+
+      if (record) {
+        if (Date.now() > record.expiresAt) {
+          otpStore.delete(normalized);
+          return new Response(
+            JSON.stringify({
+              error: 'OTP_EXPIRED',
+              message: 'Your verification code has expired. Please request a new code.',
+            }),
+            {
+              status: 400,
+              headers: { 'Content-Type': 'application/json' },
+            }
+          );
+        }
+
+        if (record.code !== cleanCode) {
+          return new Response(
+            JSON.stringify({
+              error: 'OTP_MISMATCH',
+              message: 'The verification code you entered is incorrect.',
+            }),
+            {
+              status: 400,
+              headers: { 'Content-Type': 'application/json' },
+            }
+          );
+        }
+
+        otpStore.delete(normalized);
+      }
+
+      return new Response(
+        JSON.stringify({
+          success: true,
+          verified: true,
+          phone: normalized,
+          message: 'Phone number verified successfully.',
+        }),
+        {
+          status: 200,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    return new Response(
+      JSON.stringify({
+        error: 'INVALID_ACTION',
+        message: 'Unsupported action. Use "send" or "verify".',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({
+        error: 'BAD_REQUEST',
+        message: 'Invalid request payload.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};

