+
+        // Update screen classes in the hierarchical stack
+        screens.forEach((screenEl, levelIndex) => {
+          screenEl.classList.remove('is-active', 'is-behind', 'is-deep-behind', 'is-offscreen', 'is-dragging');
+          screenEl.style.transform = '';
+          screenEl.style.opacity = '';
+
+          if (levelIndex === depth) {
