+          depthIndicatorEl.textContent = 'Level 1 · Root';
+          document.title = 'The Daily Grind | Artisanal Coffee';
+        } else if (depth === 1) {
+          const item = SEASONAL_ITEMS[topEntry.itemId];
+          navBackBtn.hidden = false;
+          navBackLabel.textContent = 'Seasonal Favorites';
+          swipeEdgeHandle.hidden = false;
+          depthIndicatorEl.textContent = 'Level 2 · Item Detail';
+          document.title = `${item ? item.title : 'Detail'} | The Daily Grind`;
+        } else {
+          const item = SEASONAL_ITEMS[topEntry.itemId];
