+        pushStack([{ view: 'home' }, { view: 'detail', itemId: normalized }]);
+      }
+
+      function drillIntoSubview(subview) {
+        if (currentStack.length < 2) return;
+        const itemId = currentStack[1].itemId;
+        pushStack([
+          { view: 'home' },
+          { view: 'detail', itemId: itemId },
