+    this._nutritionVal = this.shadowRoot.querySelector('.nutrition-val');
+    this._addBtn = this.shadowRoot.querySelector('.add-btn');
+    this._detailsLink = this.shadowRoot.querySelector('.view-details-link');
+    this._announcer = this.shadowRoot.querySelector('.live-announcer');
