+  }
+
+  disconnectedCallback() {
+    this._favBtn.removeEventListener('click', this._onFavClick);
+    this._sizeGroup.removeEventListener('click', this._onSizeClick);
+    this._sizeGroup.removeEventListener('keydown', this._onSizeKeyDown);
+    this._detailsToggle.removeEventListener('click', this._onToggleDetails);
+    this._addBtn.removeEventListener('click', this._onAddClick);
+    this._detailsLink.removeEventListener('click', this._onViewDetailsClick);
