+  }
+
+  get description() {
+    return this.getAttribute('description') || '';
+  }
+  set description(val) {
+    this.setAttribute('description', val);
+  }
+
+  get basePrice() {
+    const raw = (this.getAttribute('price') || '4.50').replace(/[^0-9.]/g, '');
+    const parsed = parseFloat(raw);
+    return Number.isFinite(parsed) ? parsed : 4.5;
+  }
