+    this._closeBtn = this.shadowRoot.querySelector('.close-btn');
+    this._img = this.shadowRoot.querySelector('.hero-img');
+    this._catBadge = this.shadowRoot.querySelector('.cat-badge');
+    this._sizeBadge = this.shadowRoot.querySelector('.size-badge');
+    this._titleEl = this.shadowRoot.querySelector('#modal-title');
+    this._priceEl = this.shadowRoot.querySelector('.modal-price');
+    this._descEl = this.shadowRoot.querySelector('#modal-desc');
+    this._specRoast = this.shadowRoot.querySelector('.spec-roast');
+    this._specNotes = this.shadowRoot.querySelector('.spec-notes');
+    this._specCal = this.shadowRoot.querySelector('.spec-cal');
+    this._specCaf = this.shadowRoot.querySelector('.spec-caf');
+    this._orderBtn = this.shadowRoot.querySelector('.order-btn');
+    this._pageLink = this.shadowRoot.querySelector('.page-link');
+
+    this._onDetailsEvent = this._onDetailsEvent.bind(this);
+    this._onClose = this._onClose.bind(this);
+    this._onBackdropClick = this._onBackdropClick.bind(this);
+    this._onKeyDown = this._onKeyDown.bind(this);
+    this._onOrderClick = this._onOrderClick.bind(this);
+  }
+
+  connectedCallback() {
+    document.addEventListener('coffee-details', this._onDetailsEvent);
+    this._closeBtn.addEventListener('click', this._onClose);
+    this._backdrop.addEventListener('click', this._onBackdropClick);
+    this._orderBtn.addEventListener('click', this._onOrderClick);
+  }
+
+  disconnectedCallback() {
+    document.removeEventListener('coffee-details', this._onDetailsEvent);
+    document.removeEventListener('keydown', this._onKeyDown);
+    this._closeBtn.removeEventListener('click', this._onClose);
+    this._backdrop.removeEventListener('click', this._onBackdropClick);
+    this._orderBtn.removeEventListener('click', this._onOrderClick);
+  }
+
+  _onDetailsEvent(event) {
+    event.preventDefault();
+    this.open(event.detail);
+  }
+
+  open(item) {
+    if (!item) return;
+    this._currentItem = item;
+    this._triggerElement = item.triggerElement || document.activeElement;
+
+    this._img.src =
+      item.image ||
+      'https://images.unsplash.com/photo-1509042239860-f550ce710b93?auto=format&fit=crop&w=800&q=80';
+    this._img.alt = item.imageAlt || item.name;
+    this._catBadge.textContent = item.badge || item.category || 'Artisanal';
+    this._sizeBadge.textContent = `${item.size || 'Medium'} (${item.sizeOz || '12oz'})`;
+    this._titleEl.textContent = item.name;
+    this._priceEl.textContent = item.formattedPrice || `$${Number(item.price || 4.5).toFixed(2)}`;
+    this._descEl.textContent = item.description;
+    this._specRoast.textContent = item.roast || 'Medium Roast';
+    this._specNotes.textContent = item.notes || 'Balanced artisanal profile';
+    this._specCal.textContent = `${item.calories || 120} kcal`;
+    this._specCaf.textContent = item.caffeine || '150mg';
+    this._orderBtn.textContent = `Add ${item.size || 'Medium'} to Order • ${
+      item.formattedPrice || ''
+    }`;
+    this._pageLink.href = item.href || '/menu';
+
+    this._backdrop.hidden = false;
+    document.addEventListener('keydown', this._onKeyDown);
+    this._closeBtn.focus();
+  }
+
+  close() {
+    this._backdrop.hidden = true;
+    document.removeEventListener('keydown', this._onKeyDown);
+    if (this._triggerElement && typeof this._triggerElement.focus === 'function') {
+      this._triggerElement.focus();
+    }
+  }
+
+  _onClose() {
+    this.close();
+  }
+
+  _onBackdropClick(event) {
+    if (event.target === this._backdrop) {
+      this.close();
+    }
+  }
+
+  _onKeyDown(event) {
+    if (this._backdrop.hidden) return;
+    if (event.key === 'Escape') {
+      event.preventDefault();
+      this.close();
+      return;
+    }
+
+    if (event.key === 'Tab') {
+      const focusable = [this._closeBtn, this._orderBtn, this._pageLink];
+      const active = this.shadowRoot.activeElement;
+      const idx = focusable.indexOf(active);
+
+      if (event.shiftKey) {
+        if (idx <= 0) {
+          event.preventDefault();
+          focusable[focusable.length - 1].focus();
+        }
+      } else {
+        if (idx === focusable.length - 1) {
+          event.preventDefault();
+          focusable[0].focus();
+        }
+      }
+    }
+  }
+
+  _onOrderClick() {
+    if (!this._currentItem) return;
+    this.dispatchEvent(
+      new CustomEvent('add-to-cart', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          ...this._currentItem,
+          quantity: 1,
+        },
+      })
+    );
+    this.close();
+  }
+}
+
+if (!customElements.get('coffee-modal')) {
+  customElements.define('coffee-modal', CoffeeModal);
+}
