+/**
+ * <rewards-calculator> Web Component
+ * Interactive Daily Grind Rewards & Bean Points calculator with accessible tabs,
+ * range input slider, and live perks projection.
+ */
+
+const TIERS = {
+  bronze: {
+    name: 'Bronze Bean',
+    rate: 10,
+    perk: 'Free birthday drink + early access to seasonal roasts',
+  },
+  silver: {
+    name: 'Silver Crema',
+    rate: 15,
+    perk: 'Free milk upgrades + 2x Bean Points on Tuesdays + birthday treat',
